-- Проверка зависимостей: если модуля нет, скрипт честно скажет об этом в чате и выгрузится.
local missingModules = {}
local function safeRequire(name)
    local ok, result = pcall(require, name)
    if ok then return result end
    missingModules[#missingModules + 1] = name
    print('[LVN Helper] Не найден модуль «' .. name .. '»: ' .. tostring(result))
    return nil
end

local imgui = safeRequire 'mimgui'
local encoding = safeRequire 'encoding'
local ffi = safeRequire 'ffi'
local keys = safeRequire 'vkeys'
local sampev = safeRequire 'lib.samp.events'

if #missingModules > 0 then
    function main()
        while not isSampAvailable() do wait(100) end
        wait(2000)
        sampAddChatMessage('[LVN Helper] Missing modules: ' .. table.concat(missingModules, ', ')
            .. '. Install them into moonloader/lib and restart the game.', 0xFFFF6060)
        thisScript():unload()
    end
    do return end
end

encoding.default = 'CP1251'
local utf8Encoding = encoding.UTF8
-- The script and mimgui buffers are UTF-8. Keep UI strings unchanged; use
-- decode only at the SA-MP boundary where text must be converted to CP1251.
local u8 = setmetatable({
    decode = function(_, text) return utf8Encoding:decode(text) end,
}, { __call = function(_, text) return text end })
local new = imgui.new

-- Кодировки: внутри скрипта и ImGui всё в UTF-8, а SA-MP отдаёт и принимает CP1251.
local function toCp(text) return utf8Encoding:decode(text) end
local function toUtf8(text)
    local ok, result = pcall(function() return utf8Encoding:encode(text) end)
    if ok and type(result) == 'string' then return result end
    return text
end

-- Нижний регистр для строк в CP1251 (string.lower кириллицу не трогает).
local function cpLower(text)
    text = text:gsub('[A-Z]', string.lower)
    local result = {}
    for i = 1, #text do
        local byte = text:byte(i)
        if byte >= 192 and byte <= 223 then byte = byte + 32
        elseif byte == 168 then byte = 184 end
        result[#result + 1] = string.char(byte)
    end
    return table.concat(result)
end

local function hasAny(text, phrases)
    for _, phrase in ipairs(phrases) do
        if text:find(toCp(phrase), 1, true) then return true end
    end
    return false
end

