local function buf(size)
    return new.char[size]()
end

local function readBuffer(value)
    return ffi.string(value)
end

local function writeBuffer(target, size, value)
    ffi.fill(target, size, 0)
    local encoded = type(value) == 'string' and value or ''
    local length = math.min(#encoded, size - 1)
    if length < #encoded and length > 0 then
        local start = length
        while start > 0 do
            local byte = encoded:byte(start)
            if byte < 0x80 or byte >= 0xC0 then break end
            start = start - 1
        end
        if start > 0 then
            local byte = encoded:byte(start)
            if byte >= 0xC0 then
                local sequenceLength = byte < 0xE0 and 2 or byte < 0xF0 and 3 or 4
                if start + sequenceLength - 1 > length then length = start - 1 end
            end
        end
    end
    if length > 0 then ffi.copy(target, encoded, length) end
end

