function profile.name()
    local name = readBuffer(myName):gsub('^%s*(.-)%s*$', '%1')
    return name ~= '' and name or 'сотрудник LV News'
end

-- Поддержка старых пользовательских шаблонов: заменяем только прежнее
-- имя ведущего и явный маркер {my_name}. Названия бизнесов не затрагиваем.
function profile.apply(text)
    text = tostring(text or '')
    local function currentName() return profile.name() end
    text = text:gsub('Vladimir_Palermo', currentName)
    text = text:gsub('Владимир Палермо', currentName)
    text = text:gsub('Владимир_Палермо', currentName)
    text = text:gsub('{my_name}', currentName)
    return text
end

-- Для новой установки: предложить найденный игровой ник в поле профиля.
-- Явно записанное пользователем имя в settings.json никогда не перезаписываем.
function profile.suggest()
    if readBuffer(myName):match('%S') then return false end
    if type(sampGetPlayerIdByCharHandle) ~= 'function'
        or type(sampGetPlayerNickname) ~= 'function'
        or type(PLAYER_PED) == 'nil' then return false end
    local ok, found, id = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not ok or not found or type(id) ~= 'number' then return false end
    local nicknameOk, nickname = pcall(sampGetPlayerNickname, id)
    if not nicknameOk or type(nickname) ~= 'string'
        or not nickname:match('^[A-Za-z][A-Za-z0-9_]+$') then return false end
    writeBuffer(myName, 64, nickname)
    return true
end

