local sloganAll = {}
local sloganCategoryNames = { 'Все категории' }
for _, group in ipairs(sloganGroups) do
    sloganCategoryNames[#sloganCategoryNames + 1] = group.name
    for _, item in ipairs(group.items) do
        sloganAll[#sloganAll + 1] = { category = group.name, text = item }
    end
end

local fieldMap = {}
for _, item in ipairs(fields) do fieldMap[item[1]] = item[2] end

local function values()
    local result = {}
    for key, value in pairs(inputs) do result[key] = readBuffer(value):gsub('^%s*(.-)%s*$', '%1') end
    return result
end

local function render(body, data)
    body = body:gsub('%[%[(.-)%]%]', function(block)
        local hasValue = false
        for key in block:gmatch('{([%w_]+)}') do
            if data[key] and data[key] ~= '' then hasValue = true end
        end
        if hasValue then return block end
        return ''
    end)
    body = body:gsub('{([%w_]+)}', function(key) return data[key] or ('{' .. key .. '}') end)
    body = body:gsub('%s+([,%.])', '%1'):gsub('([,%.])%s*([,%.])', '%1')
    return body:gsub('^%s*(.-)%s*$', '%1')
end

local function setStatus(message, color)
    statusText = message
    if type(color) == 'number' then
        local red = color % 256
        local green = math.floor(color / 256) % 256
        local blue = math.floor(color / 65536) % 256
        local alpha = math.floor(color / 16777216) % 256
        statusColor = imgui.ImVec4(red / 255, green / 255, blue / 255, alpha / 255)
    end
end

local function persistFavorites()
    if not favoritePath then return false end
    local file = io.open(favoritePath, 'w')
    if not file then return false end
    local ok, encoded = pcall(encodeJson, favorites)
    if not ok then file:close(); return false end
    file:write(encoded)
    file:close()
    return true
end

local function persistSettings()
    if not settingsPath then return false end
    local data = {
        commands = { me = readBuffer(meCommand), do_command = readBuffer(doCommand) },
        media_stages = customMediaStages,
        profile = { name = readBuffer(myName), rank = readBuffer(myRank), dnd_text = readBuffer(dndMessage), sms_keyword = readBuffer(smsFilter) },
        hotkey = { modifier = selectedModifier[0], key = selectedKey[0] },
        features = {
            remember_ad_edits = rememberAdEdits[0], dnd = dndMode[0],
            greeting = autoGreeting[0], camera_rp = autoCameraRP[0],
            sms_log = showSmsLogger[0], cheat_sheet = showCheatSheet[0], rank_tag = rankTagBinder[0],
        },
    }
    local ok, encoded = pcall(encodeJson, data)
    if not ok then return false end
    local file = io.open(settingsPath, 'w')
    if not file then return false end
    file:write(encoded)
    file:close()
    return true
end

local function validCustomCommand(command)
    return type(command) == 'string'
        and command:match('^/[A-Za-z][A-Za-z0-9_]*$') ~= nil
        and command:lower() ~= '/lvn'
end

local function sanitizeMediaStages(value)
    local result = {}
    if type(value) ~= 'table' then return result end
    for modeIndex, mode in ipairs(mediaModes) do
        local source = value[tostring(modeIndex)] or value[modeIndex]
        if type(source) == 'table' then
            local stages = {}
            for stageIndex = 1, #mode.stages do
                local text = source[tostring(stageIndex)] or source[stageIndex]
                if type(text) == 'string' then stages[tostring(stageIndex)] = text end
            end
            if next(stages) then result[tostring(modeIndex)] = stages end
        end
    end
    return result
end

local function sanitizeFavorites(value)
    local result = {}
    if type(value) ~= 'table' then return result end
    for _, favorite in ipairs(value) do
        if #result >= 40 then break end
        if type(favorite) == 'table' and type(favorite.text) == 'string' then
            result[#result + 1] = {
                name = type(favorite.name) == 'string' and favorite.name or 'Черновик',
                text = favorite.text,
            }
        end
    end
    return result
end

local function effectiveCommand(buffer, fallback)
    local command = readBuffer(buffer):gsub('^%s*(.-)%s*$', '%1')
    return validCustomCommand(command) and command or fallback
end

local function canonicalizeCommandPrefix(text, command, canonical)
    local prefix = command .. ' '
    if text:sub(1, #prefix) == prefix then
        return canonical .. text:sub(#command + 1)
    end
    return text
end

local function loadStageText(modeIndex, stageIndex)
    local mode = mediaModes[modeIndex]
    local stage = mode and mode.stages[stageIndex]
    if not stage then return '' end
    local modeStages = customMediaStages[tostring(modeIndex)] or customMediaStages[modeIndex]
    local text = modeStages and (modeStages[tostring(stageIndex)] or modeStages[stageIndex]) or stage[2]
    if modeIndex == 7 then
        text = text:gsub('^/me%s+', effectiveCommand(meCommand, '/me') .. ' ')
        text = text:gsub('^/do%s+', effectiveCommand(doCommand, '/do') .. ' ')
    end
    return text
end

local function selectSettingsStage(modeIndex, stageIndex)
    settingsMediaMode[0] = modeIndex
    settingsMediaStage[0] = stageIndex
    writeBuffer(stageEditor, 2048, loadStageText(modeIndex, stageIndex))
end

local function saveCustomStage()
    local modeIndex, stageIndex = settingsMediaMode[0], settingsMediaStage[0]
    local mode = mediaModes[modeIndex]
    if not mode or not mode.stages[stageIndex] then return end
    local text = readBuffer(stageEditor):gsub('^%s*(.-)%s*$', '%1')
    text = canonicalizeCommandPrefix(text, effectiveCommand(meCommand, '/me'), '/me')
    text = canonicalizeCommandPrefix(text, effectiveCommand(doCommand, '/do'), '/do')
    local modeKey, stageKey = tostring(modeIndex), tostring(stageIndex)
    if not customMediaStages[modeKey] then customMediaStages[modeKey] = {} end
    customMediaStages[modeKey][stageKey] = text
    writeBuffer(stageEditor, 2048, loadStageText(modeIndex, stageIndex))
    if persistSettings() then setStatus('Изменённая отыгровка сохранена.', 0xFF79D8A2)
    else setStatus('Не удалось записать настройки. Проверьте доступ к папке MoonLoader.', 0xFF7777FF) end
end

local function restoreCustomStage()
    local modeIndex, stageIndex = settingsMediaMode[0], settingsMediaStage[0]
    local modeKey, stageKey = tostring(modeIndex), tostring(stageIndex)
    local modeStages = customMediaStages[modeKey] or customMediaStages[modeIndex]
    if modeStages then
        modeStages[stageKey] = nil
        modeStages[stageIndex] = nil
        if next(modeStages) == nil then customMediaStages[modeKey] = nil; customMediaStages[modeIndex] = nil end
    end
    writeBuffer(stageEditor, 2048, loadStageText(modeIndex, stageIndex))
    if persistSettings() then setStatus('Для этой отыгровки восстановлен исходный текст.', 0xFF79D8A2)
    else setStatus('Не удалось записать настройки.', 0xFF7777FF) end
end

local function saveCustomCommands()
    local me = readBuffer(meCommand):gsub('^%s*(.-)%s*$', '%1')
    local doCmd = readBuffer(doCommand):gsub('^%s*(.-)%s*$', '%1')
    if not validCustomCommand(me) or not validCustomCommand(doCmd) then
        setStatus('Введите команды формата /me или /action. /lvn зарезервирована и не меняется.', 0xFF7777FF)
        return
    end
    writeBuffer(meCommand, 32, me)
    writeBuffer(doCommand, 32, doCmd)
    if persistSettings() then
        writeBuffer(stageEditor, 2048, loadStageText(settingsMediaMode[0], settingsMediaStage[0]))
        setStatus('RP-команды сохранены. Проверьте, поддерживает ли их сервер.', 0xFF79D8A2)
    else
        setStatus('Не удалось сохранить команды. Проверьте доступ к папке MoonLoader.', 0xFF7777FF)
    end
end

local function loadFavorites()
    local config = getGameDirectory() .. '//moonloader//config'
    if not doesDirectoryExist(config) then createDirectory(config) end
    local folder = config .. '//LVNHelper'
    if not doesDirectoryExist(folder) then createDirectory(folder) end
    favoritePath = folder .. '//favorites.json'
    orgRulesPath = folder .. '//organization_rules.txt'
    settingsPath = folder .. '//settings.json'
    memoryPath = folder .. '//memory.json'
    if doesFileExist(favoritePath) then
        local file = io.open(favoritePath, 'r')
        if file then
            local raw = file:read('*a')
            file:close()
            local ok, decoded = pcall(decodeJson, raw)
            if ok then favorites = sanitizeFavorites(decoded) end
        end
    end
    if doesFileExist(settingsPath) then
        local file = io.open(settingsPath, 'r')
        if file then
            local raw = file:read('*a')
            file:close()
            local ok, decoded = pcall(decodeJson, raw)
            if ok and type(decoded) == 'table' then
                local commands = decoded.commands
                if type(commands) == 'table' then
                    if validCustomCommand(commands.me) then writeBuffer(meCommand, 32, commands.me) end
                    if validCustomCommand(commands.do_command) then writeBuffer(doCommand, 32, commands.do_command) end
                end
                customMediaStages = sanitizeMediaStages(decoded.media_stages)
                if type(decoded.profile) == 'table' then
                    writeBuffer(myName, 64, decoded.profile.name or '')
                    writeBuffer(myRank, 64, decoded.profile.rank or 'Ведущий')
                    if type(decoded.profile.dnd_text) == 'string' and decoded.profile.dnd_text ~= '' then
                        writeBuffer(dndMessage, 160, decoded.profile.dnd_text)
                    end
                    if type(decoded.profile.sms_keyword) == 'string' then
                        writeBuffer(smsFilter, 64, decoded.profile.sms_keyword)
                    end
                end
                if type(decoded.hotkey) == 'table' then
                    local modifier = tonumber(decoded.hotkey.modifier)
                    local key = tonumber(decoded.hotkey.key)
                    if modifier and modifier >= 0 and modifier < #availableModifiers then selectedModifier[0] = modifier end
                    if key and key >= 0 and key < #availableKeys then selectedKey[0] = key end
                end
                if type(decoded.features) == 'table' then
                    rememberAdEdits[0] = decoded.features.remember_ad_edits == true
                    dndMode[0] = decoded.features.dnd == true
                    autoGreeting[0] = decoded.features.greeting == true
                    autoCameraRP[0] = decoded.features.camera_rp == true
                    showSmsLogger[0] = decoded.features.sms_log == true
                    showCheatSheet[0] = decoded.features.cheat_sheet == true
                    rankTagBinder[0] = decoded.features.rank_tag == true
                end
            end
        end
    end
    if doesFileExist(memoryPath) then
        local file = io.open(memoryPath, 'r')
        if file then
            local raw = file:read('*a')
            file:close()
            local ok, decoded = pcall(decodeJson, raw)
            if ok and type(decoded) == 'table' then
                for source, edited in pairs(decoded) do
                    if type(source) == 'string' and type(edited) == 'string' and source ~= '' and edited ~= '' then
                        adMemory[source] = edited
                    end
                end
            end
        end
    end
    selectSettingsStage(settingsMediaMode[0], settingsMediaStage[0])
    local rulesFile = io.open(orgRulesPath, 'r')
    if rulesFile then
        local rulesText = rulesFile:read('*a')
        rulesFile:close()
        writeBuffer(orgRules, 4096, rulesText)
    end
end

local function saveOrgRules()
    if not orgRulesPath then setStatus('Папка настроек ещё не готова.', 0xFF7777FF); return end
    local file = io.open(orgRulesPath, 'w')
    if not file then setStatus('Не удалось сохранить заметки о правилах организации.', 0xFF7777FF); return end
    file:write(readBuffer(orgRules))
    file:close()
    setStatus('Личные заметки о правилах организации сохранены.', 0xFF79D8A2)
end

local function saveFavorite(customName)
    local text = readBuffer(output):gsub('^%s*(.-)%s*$', '%1')
    if text == '' then setStatus('Сначала соберите черновик.', 0xFF60A8FF); return end
    local title = customName or (templates[selectedTemplate].name .. ' · ' .. os.date('%H:%M'))
    favorites[#favorites + 1] = { name = title, text = text }
    while #favorites > 40 do table.remove(favorites, 1) end
    selectedFavorite = #favorites
    if persistFavorites() then setStatus('Черновик добавлен в избранное.', 0xFF79D8A2)
    else setStatus('Не удалось сохранить файл избранного. Проверьте доступ к папке MoonLoader.', 0xFF7777FF) end
end

local function deleteFavorite(index)
    if index < 1 or index > #favorites then return end
    table.remove(favorites, index)
    selectedFavorite = math.min(selectedFavorite, #favorites)
    persistFavorites()
end

local function selectMediaStage(stage)
    local text = stage[2]
    for i, candidate in ipairs(mediaModes[selectedMediaMode].stages) do
        if candidate == stage then text = loadStageText(selectedMediaMode, i); break end
    end
    local replacements = {
        topic = readBuffer(mediaTopic):gsub('^%s*(.-)%s*$', '%1'),
        host = (readBuffer(mediaHost):gsub('^%s*(.-)%s*$', '%1')) ~= '' and readBuffer(mediaHost):gsub('^%s*(.-)%s*$', '%1') or profile.name(),
        guest = readBuffer(mediaGuest):gsub('^%s*(.-)%s*$', '%1'),
        material = readBuffer(mediaMaterial):gsub('^%s*(.-)%s*$', '%1'),
        source = readBuffer(mediaSource):gsub('^%s*(.-)%s*$', '%1'),
        my_name = profile.name(),
        my_rank = readBuffer(myRank):gsub('^%s*(.-)%s*$', '%1'),
    }
    local defaults = { topic = 'указанная тема', host = profile.name(), guest = 'гость', material = 'уточните материал', source = 'укажите источник', my_name = profile.name(), my_rank = 'должность' }
    text = text:gsub('{([%w_]+)}', function(key)
        return replacements[key] ~= nil and replacements[key] ~= '' and replacements[key] or defaults[key] or ('[' .. key .. ']')
    end)
    writeBuffer(output, 4096, profile.apply(text))
    findings = {}
    setStatus('Фраза «' .. stage[1] .. '» готова к правке или ручной вставке.', 0xFF79D8A2)
end

local function persistAdMemory()
    if not memoryPath then return false end
    local ok, encoded = pcall(encodeJson, adMemory)
    if not ok then return false end
    local file = io.open(memoryPath, 'w')
    if not file then return false end
    file:write(encoded)
    file:close()
    return true
end

-- Память правок: ключ и значение хранятся в UTF-8 (безопасно для JSON),
-- а с диалогом SA-MP работаем в CP1251.
function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
    if not rememberAdEdits[0] or type(title) ~= 'string' or type(text) ~= 'string' then return end
    local lowerTitle = cpLower(title)
    if not lowerTitle:find(toCp('объявлен'), 1, true) and not lowerTitle:find(toCp('редактирован'), 1, true) then return end
    lastAdDialogId = dialogId
    local rawText = text:match(toCp('[Тт]екст:') .. '%s*([^\r\n]+)') or ''
    rawText = rawText:gsub('{%x%x%x%x%x%x}', '')
    lastRawAdText = rawText:gsub('^%s*(.-)%s*$', '%1')
    local remembered = adMemory[toUtf8(lastRawAdText)]
    if remembered and remembered ~= '' then
        local expectedDialog = dialogId
        lua_thread.create(function()
            wait(20)
            if rememberAdEdits[0] and lastAdDialogId == expectedDialog and sampIsDialogActive() then
                sampSetCurrentDialogEditboxText(toCp(remembered))
            end
        end)
    end
end

function sampev.onSendDialogResponse(dialogId, button, listboxId, input)
    if not rememberAdEdits[0] or dialogId ~= lastAdDialogId or button ~= 1 then return end
    local edited = type(input) == 'string' and input:gsub('^%s*(.-)%s*$', '%1') or ''
    if lastRawAdText == '' or edited == '' or edited == lastRawAdText then return end
    adMemory[toUtf8(lastRawAdText)] = toUtf8(edited)
    if persistAdMemory() then setStatus('Правка объявления сохранена для повторного текста.', 0xFF79D8A2) end
end

local function trimText(text) return (text:gsub('^%s*(.-)%s*$', '%1')) end

-- Сообщения чата приходят в CP1251 и с цветовыми тегами {RRGGBB}; приводим к чистому UTF-8.
local function captureChatLine(clean, color)
    -- Только диагностика: SMS не анализируются и не учитываются для конкурса.
    if chatDebug[0] then
        if #chatDebugLog>=40 then table.remove(chatDebugLog,1) end
        chatDebugLog[#chatDebugLog+1]={text=clean,time=os.date('%H:%M:%S')}
    end
end

