local phraseGroups={'Все', 'Подводка к вопросу', 'После вопроса', 'Подсказки', 'Итоги раунда', 'Таблица и борьба', 'Финал'}
local contest={
    round=1, selected=1, mode='bank', scores={}, used={}, awards={}, winner=nil,
    questionSent=false, startedAt=0, customQuestion='', customAnswer='', customHint='',
    info='Выберите вопрос из банка или создайте свой. Отправьте его кнопкой ниже.',
    draftKind='', draftStepIndex=0, introIndex=1, outroIndex=1, startDone={}, endDone={}, resetArmed=false,
    championshipMode=false, championshipTiebreak=false,
}
local scoresPath
-- Основной чемпионат: 1–10 лёгкие, 11–17 средние, 18–25 сложные.
local championshipPlan={{first=1,last=10,level=1,name='Разминка'},
    {first=11,last=17,level=2,name='Основной этап'},
    {first=18,last=25,level=3,name='Финальное испытание'}}
local function championshipStage()
    if not contest.championshipMode then return nil end
    if contest.round>25 then
        return contest.championshipTiebreak and 3 or nil
    end
    for _,phase in ipairs(championshipPlan) do
        if contest.round>=phase.first and contest.round<=phase.last then return phase.level end
    end
    return nil
end
local function championshipPhase()
    if not contest.championshipMode then return nil end
    if contest.round>25 then
        return contest.championshipTiebreak and {name='Тай-брейк',level=3,first=26,last=99} or nil
    end
    for _,phase in ipairs(championshipPlan) do
        if contest.round>=phase.first and contest.round<=phase.last then return phase end
    end
    return nil
end
local function quizTrim(s) return tostring(s or ''):gsub('^%s*(.-)%s*$', '%1') end
local function quizCopyTable(source)
    if type(source)~='table' then return {} end
    local copy={}
    for k,v in pairs(source) do copy[k]=v end
    return copy
end
local function question()
    if contest.mode=='custom' then
        if contest.customQuestion=='' then return nil end
        return {kind='Свой вопрос',question=contest.customQuestion,answer=contest.customAnswer,hint=contest.customHint,level=championshipStage() or 2}
    end
    if contest.mode=='bank' then return questionBank[contest.selected] end
    return nil
end
local function storage()
    if not scoresPath then return false end
    local data={version=3,round=contest.round,selected=contest.selected,mode=contest.mode,
       championshipMode=contest.championshipMode,championshipTiebreak=contest.championshipTiebreak,
       scores=contest.scores,used=contest.used,awards=contest.awards,winner=contest.winner,
       questionSent=contest.questionSent,startedAt=contest.startedAt,
       customQuestion=contest.customQuestion,customAnswer=contest.customAnswer,
       customHint=contest.customHint,startDone=contest.startDone,endDone=contest.endDone}
    local ok,json=pcall(encodeJson,data)
    if not ok or type(json)~='string' then return false end
    local f=io.open(scoresPath,'w')
    if not f then return false end
    f:write(json); f:close(); return true
end
local function load()
    local folder=getGameDirectory() .. '//moonloader//config//LVNHelper'
    if not doesDirectoryExist(folder) then createDirectory(folder) end
    scoresPath=folder .. '//quiz_scores.json'
    local f=io.open(scoresPath,'r'); if not f then return end
    local raw=f:read('*a'); f:close()
    local ok,data=pcall(decodeJson,raw)
    if not ok or type(data)~='table' then return end
    if type(data.round)=='number' then contest.round=math.max(1,math.min(99,math.floor(data.round))) end
    if type(data.scores)=='table' then
        for name,n in pairs(data.scores) do
            if type(name)=='string' and name:match('^[%w_]+$') and #name<=32
               and type(n)=='number' and n>=0 and n<=1000 then
                contest.scores[name]=math.floor(n)
            end
        end
    end
    if data.version==2 or data.version==3 then
        if data.version==3 then
            contest.championshipMode=data.championshipMode==true
            contest.championshipTiebreak=contest.championshipMode and data.championshipTiebreak==true
        end
        if type(data.selected)=='number' and questionBank[data.selected] then contest.selected=data.selected end
        if data.mode=='bank' or data.mode=='custom' or data.mode=='none' then contest.mode=data.mode end
        if type(data.used)=='table' then
            for k,v in pairs(data.used) do
                if tonumber(k) and questionBank[tonumber(k)] and v==true then contest.used[tostring(tonumber(k))]=true end
            end
        end
        if type(data.awards)=='table' then
            for _,item in ipairs(data.awards) do
                if type(item)=='table' and type(item.name)=='string' and type(item.round)=='number' then
                    contest.awards[#contest.awards+1]={name=item.name,round=item.round}
                    if #contest.awards>=300 then break end
                end
            end
        end
        if type(data.winner)=='table' and type(data.winner.name)=='string' then
            contest.winner={name=data.winner.name,round=tonumber(data.winner.round) or contest.round,
                score=tonumber(data.winner.score) or 0}
        end
        contest.questionSent=data.questionSent==true
        if type(data.startedAt)=='number' and data.startedAt>=0 then contest.startedAt=data.startedAt end
        if type(data.customQuestion)=='string' then contest.customQuestion=data.customQuestion:sub(1,500) end
        if type(data.customAnswer)=='string' then contest.customAnswer=data.customAnswer:sub(1,200) end
        if type(data.customHint)=='string' then contest.customHint=data.customHint:sub(1,250) end
        for _,block in ipairs({{'startDone',#startSteps},{'endDone',#endSteps}}) do
            local sourceDone=data[block[1]]
            if type(sourceDone)=='table' then
                for k,v in pairs(sourceDone) do
                    local id=tonumber(k)
                    if id and id>=1 and id<=block[2] and id==math.floor(id) and v==true then
                        contest[block[1]][tostring(id)]=true
                    end
                end
            end
        end
    else
        -- Для старой версии восстанавливаем только баллы и номер раунда: без догадок о текущем победителе.
        contest.mode='bank'; contest.selected=math.min(contest.round,#questionBank)
    end
end
local function setDraft(text,kind)
    text=quizTrim(profile.apply(text))
    if text=='' then contest.info='Пустая реплика.'; return false end
    writeBuffer(output,4096,text)
    contest.draftKind=kind or 'phrase'
    contest.info='Реплика готова: отредактируйте её или нажмите «Отправить в эфир».'
    return true
end
local function announceText(message,kind)
    return setDraft(message,kind)
end
local function choose(index)
    if not questionBank[index] then return false end
    if contest.winner or contest.questionSent then
        contest.info='Текущий раунд уже начат или завершён. Сначала нажмите «Следующий раунд».'
        return false
    end
    local required=championshipStage()
    if contest.championshipMode and not required then
        contest.info='Основные 25 раундов завершены. Подведите итоги или начните тай-брейк.'
        return false
    end
    if required and questionBank[index].level~=required then
        contest.info='Раунд '..contest.round..': выберите уровень «'..difficultyNames[required]..'».'
        return false
    end
    contest.selected=index;contest.mode='bank';contest.draftKind=''
    contest.info='Выбран вопрос: '..questionBank[index].kind..'. Можно подготовить или сразу отправить.'
    storage(); return true
end
local function chooseCustom(text,answer,hint)
    if contest.winner or contest.questionSent then
        contest.info='Сначала завершите текущий раунд.';return false end
    if contest.championshipMode and not championshipStage() then
        contest.info='Основные 25 раундов завершены.'; return false end
    text=quizTrim(text):gsub('[\r\n]+',' ')
    answer=quizTrim(answer):gsub('[\r\n]+',' ')
    hint=quizTrim(hint):gsub('[\r\n]+',' ')
    if text=='' or answer=='' then contest.info='Для своего вопроса заполните вопрос и правильный ответ.';return false end
    contest.customQuestion=text:sub(1,500);contest.customAnswer=answer:sub(1,200)
    contest.customHint=hint:sub(1,250);contest.mode='custom';contest.selected=0
    contest.draftKind='';contest.info='Свой вопрос выбран для раунда '..contest.round..'.'
    storage(); return true
end
local function prepareQuestion()
    local q=question()
    if not q then contest.info='Сначала выберите вопрос.';return false end
    if contest.winner then contest.info='Этот раунд уже завершён. Перейдите к следующему.';return false end
    local required=championshipStage()
    if contest.championshipMode and (not required or q.level~=required) then
        contest.info='Уровень вопроса не соответствует этапу чемпионата.';return false end
    local label=contest.championshipMode and ('Раунд '..contest.round..(contest.round<=25 and '/25' or ' (тай-брейк)'))
        or ('Раунд '..contest.round)
    return setDraft(label..'! '..q.question,'question')
end
local function hostText()
    return profile.name()
end
local function musicSelect(index)
    if not music[index] then return false end
    return setDraft(music[index].line,'music')
end
local function markSent()
    if contest.draftKind=='step_start' and startSteps[contest.draftStepIndex] then
        contest.startDone[tostring(contest.draftStepIndex)]=true
        storage()
    elseif contest.draftKind=='step_end' and endSteps[contest.draftStepIndex] then
        contest.endDone[tostring(contest.draftStepIndex)]=true
        storage()
    end
    if contest.draftKind=='question' then
        contest.questionSent=true
        if contest.mode=='bank' then contest.used[tostring(contest.selected)]=true end
        storage()
        contest.info='Вопрос отправлен. Сравните ответы в игровом чате и укажите победителя вручную.'
    else
        contest.info='Реплика отправлена в чат. Если включён эфир /n, она прозвучит в эфире.'
    end
end
local function award(name, answer)
    name=quizTrim(name);answer=quizTrim(answer)
    if contest.winner then contest.info='Бал за этот раунд уже выдан. Можно отменить его.';return false end
    if not question() then contest.info='Сначала выберите вопрос.';return false end
    if not name:match('^[%a%d_]+$') or #name<3 or #name>24 then
        contest.info='Введите игровой ник латиницей, например Ivan_Petrov.';return false end
    for existing in pairs(contest.scores) do if existing:lower()==name:lower() then name=existing;break end end
    -- Ответ вводит ведущий для самопроверки, решение о балле остаётся за ним.
    contest.scores[name]=(contest.scores[name] or 0)+1
    contest.winner={name=name, round=contest.round, score=contest.scores[name], answer=answer}
    contest.awards[#contest.awards+1]={name=name,round=contest.round}
    contest.info='Игрок '..name..' получил +1. Готова кнопка «Объявить результат».'
    storage(); return true
end
local function announceRound()
    if contest.winner then
        local w=contest.winner
        return setDraft(string.format('Первым правильно ответил %s! +1 балл, всего у него %d.',w.name,w.score),'result')
    end
    return setDraft('В этом раунде победитель не определён. Переходим к следующему вопросу!','result')
end
local function nextRound()
    if contest.round>=99 then contest.info='Достигнут предел в 99 раундов.';return false end
    if contest.championshipMode and not contest.questionSent then
        contest.info='Сначала отправьте вопрос текущего раунда. Для раунда без правильного ответа балл не нужен.'
        return false
    end
    if contest.championshipMode then
        if contest.round==25 and not contest.championshipTiebreak then
            contest.info='Все 25 раундов завершены! Нажмите «ИТОГ КОНКУРСА». Если ничья — запустите тай-брейк.'
            return false
        end
        if contest.round>25 and contest.championshipTiebreak then
            local rows={}
            for n,s in pairs(contest.scores) do rows[#rows+1]={name=n,score=s} end
            table.sort(rows,function(a,b) return a.score>b.score end)
            if #rows<2 or rows[1].score~=rows[2].score then
                contest.info='Ничья снята! Объявите итог чемпионата.';return false
            end
        end
    end
    contest.round=contest.round+1
    contest.winner=nil;contest.questionSent=false;contest.mode='none';contest.selected=0
    contest.draftKind=''
    if contest.championshipMode and contest.round==11 then
        contest.info='Переход: 10 лёгких завершены. Начинаются 7 средних вопросов!'
    elseif contest.championshipMode and contest.round==18 then
        contest.info='ФИНАЛ: 7 средних завершены. Начинаются 8 сложных вопросов!'
    else
        contest.info='Раунд '..contest.round..'. Выберите следующий вопрос из банка.'
    end
    storage();return true
end
local function undo()
    local item=table.remove(contest.awards)
    if not item then contest.info='Пока нечего отменять.';return false end
    contest.scores[item.name]=math.max(0,(contest.scores[item.name] or 0)-1)
    if contest.winner and contest.winner.name==item.name and contest.winner.round==item.round then contest.winner=nil end
    contest.info='Последний балл игрока '..item.name..' отменён.'
    storage();return true
end
local function adjust(name,delta)
    if type(name)~='string' or contest.scores[name]==nil then return false end
    contest.scores[name]=math.max(0,contest.scores[name]+delta)
    if contest.winner and contest.winner.name==name then contest.winner.score=contest.scores[name] end
    contest.info='Счёт '..name..': '..contest.scores[name]..' (ручная корректировка).'
    storage();return true
end
local function ranking()
    local rows={}
    for name,score in pairs(contest.scores) do rows[#rows+1]={name=name,score=score} end
    table.sort(rows,function(a,b) if a.score==b.score then return a.name<b.name end return a.score>b.score end)
    return rows
end
local function leaderLine()
    local rows=ranking()
    if #rows==0 then contest.info='Таблица пока пуста.';return false end
    local top={}
    for i=1,math.min(3,#rows) do top[#top+1]=string.format('%d) %s - %d',i,rows[i].name,rows[i].score) end
    return setDraft('Таблица лидеров: '..table.concat(top,'; ')..'.','leaders')
end
local function finish()
    if contest.championshipMode and (contest.round<25 or not contest.questionSent) then
        contest.info='Чемпионат ещё идёт. Всего 25 раундов: 10 лёгких, 7 средних и 8 сложных.'
        return false
    end
    local rows=ranking()
    if #rows==0 then contest.info='Пока нет участников с баллами.';return false end
    if #rows>1 and rows[1].score==rows[2].score then
        local count=0
        for _,r in ipairs(rows) do if r.score==rows[1].score then count=count+1 else break end end
        return setDraft(string.format('Ничья! %d игрока набрали по %d баллов. Решит дополнительный вопрос!',count,rows[1].score),'final')
    end
    return setDraft(string.format('Победитель «Битвы умов» - %s! %d баллов, приз - 250 тысяч вирт!',rows[1].name,rows[1].score),'final')
end
local function reset()
    if not contest.resetArmed then
        contest.resetArmed=true;contest.info='Для нового конкурса нажмите «Новый конкурс» ещё раз.';return false
    end
    contest.round=1;contest.selected=1;contest.mode='bank';contest.scores={};contest.used={}
    contest.awards={};contest.winner=nil;contest.questionSent=false;contest.startedAt=0
    contest.draftKind='';contest.draftStepIndex=0;contest.resetArmed=false;contest.introIndex=1;contest.outroIndex=1;contest.startDone={};contest.endDone={}
    contest.championshipTiebreak=false
    contest.info=contest.championshipMode and 'Новый чемпионат: 25 раундов (10 лёгких, 7 средних, 8 сложных).'
        or 'Новый конкурс готов. Выберите вопрос и начните эфир.'
    storage();return true
end
local function phraseText(raw)
    local selected=question()
    local vars={host=hostText(),round=tostring(contest.round),
        name=contest.winner and contest.winner.name or 'наш участник',
        score=tostring(contest.winner and contest.winner.score or 0),
        answer=selected and selected.answer or 'уточняется',
        category=selected and selected.kind or 'Эрудиция',
        championship_rules=contest.championshipMode and
            'В чемпионате 25 вопросов: 10 лёгких, 7 средних и 8 сложных. За каждый верный ответ первым — один балл.'
            or 'За каждый первый правильный ответ начислим один балл, затем сравним очки.'}
    return tostring(raw):gsub('{([%w_]+)}',function(k) return vars[k] or ('{'..k..'}') end)
end
local function prepareStep(which,index)
    local steps=which=='start' and startSteps or which=='end' and endSteps or nil
    local entry=steps and steps[index]
    if not entry then return false end
    if setDraft(phraseText(entry.text),'step_'..which) then
        contest.draftStepIndex=index
        return true
    end
    return false
end
local function preparePhrase(index)
    local entry=phraseLibrary[index]
    if not entry then return false end
    contest.draftStepIndex=0
    return setDraft(phraseText(entry.text),'phrase')
end
local function prepareHint()
    local selected=question()
    if not selected or not selected.hint or selected.hint=='' then
        contest.info='У выбранного вопроса нет подсказки.';return false end
    contest.draftStepIndex=0
    return setDraft('Подсказка: '..selected.hint,'hint')
end
local function selectSurprise(level,kind)
    if contest.winner or contest.questionSent then
        contest.info='Раунд уже начат. Сначала перейдите к следующему.';return false
    end
    local required=championshipStage()
    if contest.championshipMode and not required then
        contest.info='Основные раунды завершены: нужна развязка чемпионата.';return false
    end
    if required then level=required end
    local pool={}
    for i,q in ipairs(questionBank) do
        if (level==0 or q.level==level) and (kind=='Все' or q.kind==kind)
           and not contest.used[tostring(i)] then pool[#pool+1]=i end
    end
    if #pool==0 then contest.info='В этой категории не осталось новых вопросов. Смените фильтры.';return false end
    return choose(pool[math.random(1,#pool)])
end
local function toggleChampionship()
    if contest.questionSent or contest.winner then
        contest.info='Сменить формат можно до начала следующего раунда. Сначала завершите текущий.'
        return false
    end
    if not contest.championshipMode and contest.round>25 then
        contest.info='Невозможно начать чемпионат после 25-го раунда. Начните новый конкурс.'
        return false
    end
    contest.championshipMode=not contest.championshipMode
    contest.championshipTiebreak=false
    if not contest.questionSent and not contest.winner and contest.mode=='bank'
        and questionBank[contest.selected] and championshipStage()
        and questionBank[contest.selected].level~=championshipStage() then
        contest.selected=0;contest.mode='none'
    end
    contest.draftKind=''
    contest.info=contest.championshipMode
        and 'Режим «Чемпионат» включён: 10 лёгких, 7 средних и 8 сложных. Выбор вопроса остаётся за вами.'
        or 'Режим свободной викторины включён.'
    storage();return true
end
local function preparePhase()
    if not contest.championshipMode then
        contest.info='Для переходов между этапами включите режим «Чемпионат».';return false end
    if contest.round<=10 then
        return setDraft('Начинаем разминку! Впереди 10 лёгких вопросов. Проверим скорость и знания!','phase')
    elseif contest.round<=17 then
        return setDraft('Первый этап позади! Теперь 7 вопросов средней сложности. Борьба набирает обороты!','phase')
    elseif contest.round<=25 then
        return setDraft('ФИНАЛЬНЫЙ ЭТАП! Впереди 8 сложных вопросов. Теперь каждый балл на вес золота!','phase')
    end
    return setDraft('Ничья по очкам! Начинается дополнительный сложный вопрос для определения чемпиона!','phase')
end
local function startTiebreak()
    if not contest.championshipMode or contest.round<25 or not contest.questionSent then
        contest.info='Тай-брейк доступен после отправки всех 25 основных вопросов чемпионата.';return false end
    local rows={}
    for n,s in pairs(contest.scores) do rows[#rows+1]={name=n,score=s} end
    table.sort(rows,function(a,b) return a.score>b.score end)
    if #rows<2 or rows[1].score~=rows[2].score then
        contest.info='Ничьи за первое место нет — можно объявить чемпиона.';return false end
    if contest.round>=99 then contest.info='Достигнут предел раундов.';return false end
    contest.championshipTiebreak=true
    contest.round=contest.round+1
    contest.selected=0;contest.mode='none';contest.winner=nil;contest.questionSent=false
    contest.draftKind='';contest.info='Тай-брейк! Выберите сложный вопрос для решающего раунда.'
    storage();return true
end
quizGame.bank=questionBank
quizGame.championshipPlan=championshipPlan
quizGame.championshipStage=championshipStage
quizGame.championshipPhase=championshipPhase
quizGame.toggleChampionship=toggleChampionship
quizGame.preparePhase=preparePhase
quizGame.startTiebreak=startTiebreak
quizGame.difficultyNames=difficultyNames
quizGame.startSteps=startSteps
quizGame.endSteps=endSteps
quizGame.phraseLibrary=phraseLibrary
quizGame.phraseGroups=phraseGroups
quizGame.prepareStep=prepareStep
quizGame.preparePhrase=preparePhrase
quizGame.prepareHint=prepareHint
quizGame.selectSurprise=selectSurprise
quizGame.phraseText=phraseText
quizGame.categories=categories
quizGame.music=music
quizGame.state=contest
quizGame.load=load
quizGame.save=storage
quizGame.question=question
quizGame.choose=choose
quizGame.chooseCustom=chooseCustom
quizGame.prepareQuestion=prepareQuestion
quizGame.musicSelect=musicSelect
quizGame.markSent=markSent
quizGame.award=award
quizGame.announceRound=announceRound
quizGame.nextRound=nextRound
quizGame.undo=undo
quizGame.adjust=adjust
quizGame.ranking=ranking
quizGame.leaderLine=leaderLine
quizGame.finish=finish
quizGame.reset=reset
quizGame.draft=announceText
end

local function dndReply()
    local text = readBuffer(dndMessage):gsub('[\r\n]+', ' '):gsub('^%s*(.-)%s*$', '%1')
    if text == '' then text = DEFAULT_DND_TEXT end
    return text
end

function sampev.onServerMessage(color, text)
    if type(text) ~= 'string' then return end
    local ok, utf8Text = pcall(function() return utf8Encoding:encode(text) end)
    if not ok or type(utf8Text) ~= 'string' then return end
    utf8Text = utf8Text:gsub('{%x%x%x%x%x%x}', '')
    captureChatLine(utf8Text, color)
    if dndMode[0] and (utf8Text:find('Телефон звонит', 1, true) or utf8Text:find('звонит Вам', 1, true)) then
        local now = os.clock()
        local caller = utf8Text:match('Звонит ([%w_]+)') or utf8Text:match('от (%d+)')
        if caller and now - lastDndResponse > 8 then
            lastDndResponse = now
            lua_thread.create(function()
                wait(500)
                if dndMode[0] then
                    sampSendChat('/h')
                    wait(1000)
                    if dndMode[0] then sampSendChat(toCp('/sms ' .. caller .. ' ' .. dndReply())) end
                end
            end)
        end
    end
end

-- ═══════════ Отыгровки по командам ═══════════
-- Любая команда из списка перехватывается при отправке в чат: скрипт проигрывает строки
-- отыгровки по очереди, а исходную серверную команду (например /showpass) может отправить
-- в нужный момент сам.
local bindsPath
local bindGroups = {}
local bindRunning, bindCancel, selfSending = false, false, false
local configWritable = false
local BIND_MAX_GROUPS, BIND_MAX_BINDS = 20, 60
-- Встроенные этапы интервью редактируются в обычном меню «Отыгровки».
-- Поле flow_stage — постоянный идентификатор, а /sv1 и /sv2 остаются игровыми командами.
local interviewApi = { stages = {
    hello = '/sv1', question = '/sv1', ask_photo = '/sv2',
    take_photo = '/sv2', no_photo = '/sv2', decline_photo = '/sv2',
} }

interviewApi.normalizeCommand = function(text)
    text = trimText(text or '')
    if text ~= '' and text:sub(1, 1) ~= '/' then text = '/' .. text end
    return text
end

interviewApi.validBindCommand = function(command, flowStage)
    if type(command) ~= 'string' or command:match('^/[A-Za-z][A-Za-z0-9_]*$') == nil
        or #command > 24 or command:lower() == '/lvn' then return false end
    if flowStage ~= nil then
        return interviewApi.stages[flowStage] == command:lower()
    end
    return command:lower() ~= '/sv1' and command:lower() ~= '/sv2'
end

interviewApi.clampDelay = function(value)
    value = tonumber(value) or 1200
    return math.max(200, math.min(10000, math.floor(value)))
end

