local function sanitizeBindGroups(value)
    local result = {}
    if type(value) ~= 'table' then return result end
    for _, group in ipairs(value) do
        if #result >= BIND_MAX_GROUPS then break end
        if type(group) == 'table' and type(group.name) == 'string' and group.name ~= '' then
            local clean = { name = group.name:sub(1, 60), binds = {} }
            if type(group.binds) == 'table' then
                for _, bind in ipairs(group.binds) do
                    if #clean.binds >= BIND_MAX_BINDS then break end
                    local stage = type(bind) == 'table' and bind.flow_stage or nil
                    if type(bind) == 'table' and type(bind.name) == 'string' and type(bind.lines) == 'string'
                        and interviewApi.validBindCommand(bind.command, stage) then
                        clean.binds[#clean.binds + 1] = {
                            name = bind.name:sub(1, 60), command = bind.command, lines = bind.lines:sub(1, 2000),
                            delay = interviewApi.clampDelay(bind.delay), original = stage == nil and bind.original == true,
                            enabled = bind.enabled ~= false, flow_stage = stage,
                        }
                    end
                end
            end
            result[#result + 1] = clean
        end
    end
    return result
end

local function persistBinds()
    if not bindsPath then return false end
    local ok, encoded = pcall(encodeJson, bindGroups)
    if not ok then return false end
    local file = io.open(bindsPath, 'w')
    if not file then return false end
    file:write(encoded)
    file:close()
    return true
end

-- Находит один из этапов спецпроекта, независимо от названия группы.
interviewApi.findStage = function(stageId)
    for _, group in ipairs(bindGroups) do
        for _, bind in ipairs(group.binds) do
            if bind.flow_stage == stageId then return bind end
        end
    end
    return nil
end

-- Обновление старой установки: добавляем новые этапы, не трогая чужие правки.
interviewApi.ensureStages = function()
    local presets = presetBindGroups()
    local wanted = presets[#presets]
    local target
    for _, group in ipairs(bindGroups) do
        if group.name == wanted.name then target = group; break end
    end
    local added = 0
    for _, preset in ipairs(wanted.binds) do
        if not interviewApi.findStage(preset.flow_stage) then
            if not target then
                if #bindGroups >= BIND_MAX_GROUPS then break end
                target = { name = wanted.name, binds = {} }
                bindGroups[#bindGroups + 1] = target
            end
            if #target.binds >= BIND_MAX_BINDS then break end
            target.binds[#target.binds + 1] = preset
            added = added + 1
        end
    end
    return added
end

local function loadBinds()
    local folder = getGameDirectory() .. '//moonloader//config//LVNHelper'
    bindsPath = folder .. '//binds.json'
    local probe = io.open(folder .. '//.write_test', 'w')
    if probe then probe:close(); os.remove(folder .. '//.write_test'); configWritable = true end
    local loaded = false
    if doesFileExist(bindsPath) then
        local file = io.open(bindsPath, 'r')
        if file then
            local raw = file:read('*a')
            file:close()
            local ok, decoded = pcall(decodeJson, raw)
            if ok and type(decoded) == 'table' then bindGroups = sanitizeBindGroups(decoded); loaded = true end
        end
    end
    if not loaded then bindGroups = presetBindGroups() end
    if interviewApi.ensureStages() > 0 or not loaded then persistBinds() end
end

local function bindCommandOwner(command, exceptGroup, exceptIndex)
    local lowerCmd = command:lower()
    for gi, group in ipairs(bindGroups) do
        for bi, bind in ipairs(group.binds) do
            -- /sv1 и /sv2 принадлежат поэтапным интервью, не считаются конфликтом.
            if not bind.flow_stage and bind.command:lower() == lowerCmd
                and not (gi == exceptGroup and bi == exceptIndex) then return bind end
        end
    end
    return nil
end

-- Добавляет стандартные отыгровки, которых ещё нет (по команде); ваши правки не трогает.
local function restoreDefaultBinds()
    local added = 0
    for _, preset in ipairs(presetBindGroups()) do
        local target
        for _, group in ipairs(bindGroups) do if group.name == preset.name then target = group; break end end
        for _, bind in ipairs(preset.binds) do
            local missing = bind.flow_stage and not interviewApi.findStage(bind.flow_stage)
                or (not bind.flow_stage and not bindCommandOwner(bind.command))
            if missing and #bindGroups <= BIND_MAX_GROUPS then
                if not target then target = { name = preset.name, binds = {} }; bindGroups[#bindGroups + 1] = target end
                target.binds[#target.binds + 1] = bind
                added = added + 1
            end
        end
    end
    persistBinds()
    return added
end

local function expandBindLine(line, args)
    local arg = toUtf8(args or '')
    local id = arg:match('^%S+') or ''
    local name = profile.name()
    local rank = trimText(readBuffer(myRank))
    if rank == '' then rank = 'Сотрудник' end
    line = line:gsub('{arg}', function() return arg end)
    line = line:gsub('{id}', function() return id end)
    line = line:gsub('{name}', function() return name end)
    line = line:gsub('{rank}', function() return rank end)
    local host = profile.name()
    line = line:gsub('{host}', function() return host end)
    local meCmd, doCmd = effectiveCommand(meCommand, '/me'), effectiveCommand(doCommand, '/do')
    if line:sub(1, 4) == '/me ' then line = meCmd .. line:sub(4)
    elseif line:sub(1, 4) == '/do ' then line = doCmd .. line:sub(4) end
    return profile.apply(trimText(line))
end

local function runBind(bind, args, original)
    local delay = interviewApi.clampDelay(bind.delay)
    local sent = false
    local function sendOriginal()
        if sent or not original or not bind.original then return end
        sent = true
        selfSending = true
        sampSendChat(original)
        selfSending = false
    end
    local lines = {}
    for rawLine in (bind.lines .. '\n'):gmatch('(.-)\r?\n') do
        local line = trimText(rawLine)
        if line ~= '' then lines[#lines + 1] = line end
    end
    for i, line in ipairs(lines) do
        if bindCancel then return end
        local pause = line:match('^{wait:(%d+)}$')
        if pause then
            wait(math.min(10000, tonumber(pause)))
        elseif line == '{send}' then
            sendOriginal()
        else
            local text = expandBindLine(line, args)
            if text ~= '' then
                selfSending = true
                sampSendChat(toCp(text))
                selfSending = false
                if i < #lines then wait(delay) end
            end
        end
    end
    if not bindCancel then sendOriginal() end
end

local function startBind(bind, args, original)
    if bindRunning then
        setStatus('Отыгровка уже выполняется. Дождитесь окончания или остановите её в разделе «Отыгровки».', 0xFF60A8FF)
        return false
    end
    bindRunning, bindCancel = true, false
    local frozen = { delay = bind.delay, lines = bind.lines, original = bind.original }
    lua_thread.create(function()
        local ok, err = pcall(runBind, frozen, args, original)
        selfSending = false
        bindRunning = false
        if not ok then
            print('[LVN Helper] Ошибка отыгровки: ' .. tostring(err))
            setStatus('Ошибка отыгровки: ' .. tostring(err), 0xFF7777FF)
        end
    end)
    return true
end

-- === LVN: спецпроект «Один вопрос — весь штат» ==========================
-- Реплики хранятся в обычном binds.json и меняются в /lvn -> Отыгровки.
-- /sv1 и /sv2 запускают выбранный этап, между этапами ждём ответ игрока.
local interviewCommand
do
local interview = { step = 0 }

local function interviewInfo(message)
    setStatus(message, 0xFF79D8A2)
    sampAddChatMessage(toCp('{A78BFA}[LVN Интервью] {FFFFFF}' .. message), -1)
end

local function interviewRun(stageId, nextStep, message)
    local bind = interviewApi.findStage(stageId)
    if not bind then
        interviewInfo('Этап отсутствует. Открой /lvn -> Отыгровки и нажми «Вернуть стандартные».')
        return
    end
    if not bind.enabled then
        interviewInfo('Этот этап выключен в разделе «Отыгровки»: ' .. bind.name)
        return
    end
    if trimText(bind.lines) == '' then
        interviewInfo('В этапе нет текста: ' .. bind.name)
        return
    end
    if startBind({ original = false, delay = bind.delay, lines = bind.lines }, '', nil) then
        interview.step = nextStep
        interviewInfo(message)
    else
        interviewInfo('Сейчас идёт другая отыгровка. Повтори команду после её завершения.')
    end
end

interviewCommand = function(cmd, rawArgs)
    local args = trimText(toUtf8(rawArgs or '')):lower()
    if args == 'reset' or args == 'заново' or args == 'сброс' then
        if bindRunning then interviewInfo('Дождись окончания текущей отыгровки перед сбросом.')
        else interview.step = 0; interviewInfo('Интервью сброшено. Начни новое командой /sv1.') end
        return
    end
    if bindRunning then interviewInfo('Подожди окончания текущей отыгровки.'); return end

    if cmd == '/sv1' then
        if interview.step == 0 then
            interviewRun('hello', 1, 'Выслушай представление. Затем снова введи /sv1.')
        elseif interview.step == 1 then
            interviewRun('question', 2, 'Дождись ответа на главный вопрос, затем введи /sv2.')
        else
            interviewInfo('Вопрос уже задан. Для завершения используй /sv2; для нового интервью — /sv1 заново.')
        end
        return
    end

    if cmd == '/sv2' then
        local withoutPhoto = args == 'нет' or args == 'безфото'
        if interview.step == 2 then
            if withoutPhoto then
                interviewRun('no_photo', 0, 'Интервью завершено без фотографии. Для нового — /sv1.')
            else
                interviewRun('ask_photo', 3, 'Дождись согласия. /sv2 — фото и финал; /sv2 нет — без снимка.')
            end
        elseif interview.step == 3 then
            if withoutPhoto then
                interviewRun('decline_photo', 0, 'Без фотографии. Интервью завершено; для нового — /sv1.')
            else
                interviewRun('take_photo', 0, 'Интервью завершено. Скриншот фотографии сделай в игре вручную.')
            end
        else
            interviewInfo('Сначала введи /sv1 (знакомство), затем /sv1 повторно (главный вопрос).')
        end
    end
end
end -- замкнутая область спецпроекта

local function bindDispatch(command)
    if selfSending then return false end
    local cmd, args = command:match('^(/[%w_]+)%s*(.*)$')
    if not cmd then return false end
    local lowerCmd = cmd:lower()
    if lowerCmd == '/sv1' or lowerCmd == '/sv2' then
        interviewCommand(lowerCmd, args)
        return true
    end
    for _, group in ipairs(bindGroups) do
        for _, bind in ipairs(group.binds) do
            if bind.enabled and bind.command:lower() == lowerCmd then
                startBind(bind, args, command)
                return true
            end
        end
    end
    return false
end

function sampev.onSendCommand(command)
    if type(command) ~= 'string' then return end
    if bindDispatch(command) then return false end
    if not rankTagBinder[0] then return end
    local cmd, message = command:match('^(%/[rRfF])%s+(.+)$')
    if not cmd or not message then return end
    local rank = u8:decode(readBuffer(myRank):gsub('^%s*(.-)%s*$', '%1'))
    if rank == '' then return end
    local tag = '[' .. rank .. '] '
    if message:sub(1, #tag) == tag then return end
    -- Rewrite the outgoing RPC in place; never resend chat from inside this hook.
    return { cmd .. ' ' .. tag .. message }
end

function sampev.onSendChat(message)
    if not autoGreeting[0] or type(message) ~= 'string' then return end
    local lower = cpLower(message):gsub('^%s*(.-)%s*$', '%1')
    if lower ~= 'q' and lower ~= toCp('ку') and lower ~= 'qq' then return end
    local now = os.clock()
    if now - lastGreetingAt < 15 then return false end
    lastGreetingAt = now
    local rank = readBuffer(myRank):gsub('^%s*(.-)%s*$', '%1')
    local name = profile.name()
    if rank == '' then rank = 'Сотрудник' end
    lua_thread.create(function()
        sampSendChat(u8:decode(effectiveCommand(meCommand, '/me') .. ' достал удостоверение сотрудника LV News и раскрыл его'))
        wait(1500)
        sampSendChat(u8:decode(effectiveCommand(doCommand, '/do') .. ' В удостоверении: ' .. rank .. ' LV News — ' .. name .. '.'))
        wait(1500)
        sampSendChat(u8:decode('Приветствую. Я сотрудник редакции, чем могу помочь?'))
    end)
    return false
end

local function saveInterfaceSettings()
    if persistSettings() then setStatus('Профиль, горячая клавиша и переключатели сохранены.', 0xFF79D8A2)
    else setStatus('Не удалось сохранить настройки. Проверьте доступ к папке MoonLoader.', 0xFF7777FF) end
end

local function currentSloganRows()
    if selectedSloganCategory[0] == 0 then return sloganAll end
    local group = sloganGroups[selectedSloganCategory[0]]
    return group and group.items or {}
end

local function loadSelectedSlogan()
    local row = currentSloganRows()[selectedSlogan]
    if not row then setStatus('Сначала выберите слоган из списка.', 0xFF60A8FF); return end
    local phrase = row.text or row
    local farmNumber = readBuffer(sloganFarmNumber):gsub('%D', '')
    if farmNumber == '' then farmNumber = '3' end
    phrase = phrase:gsub('№%*', '№' .. farmNumber)
    writeBuffer(output, 4096, phrase)
    findings = {}
    setStatus('Слоган загружен в текст. Проверьте актуальность, правила рекламы и фактические условия.', 0xFF79D8A2)
end

local function paydayText()
    if not paydayDeadline then return 'Таймер не запущен' end
    local seconds = paydayDeadline - os.time()
    if seconds <= 0 then
        paydayDeadline = nil
        return 'Время таймера вышло'
    end
    return string.format('До отметки: %02d:%02d', math.floor(seconds / 60), seconds % 60)
end

local function togglePaydayTimer()
    if paydayDeadline then
        paydayDeadline = nil
        setStatus('Таймер остановлен.', 0xFF60A8FF)
        return
    end
    local minutes = tonumber(readBuffer(paydayMinutes))
    if not minutes or minutes < 1 or minutes > 1440 then
        setStatus('Укажите интервал от 1 до 1440 минут.', 0xFF7777FF)
        return
    end
    paydayTotal = math.floor(minutes * 60)
    paydayDeadline = os.time() + paydayTotal
    setStatus('Локальный таймер запущен. Он не считывает время сервера.', 0xFF79D8A2)
end

local function compose()
    local template = templates[selectedTemplate]
    local data = values()
    if data.action == '' then data.action = template.action end
    local missing = {}
    for _, key in ipairs(template.required) do
        if (data[key] or '') == '' then missing[#missing + 1] = fieldMap[key] or key end
    end
    local text = render(template.body, data)
    writeBuffer(output, 4096, text)
    findings = {}
    if #missing > 0 then
        setStatus('Черновик собран. Заполните обязательные поля: ' .. table.concat(missing, ', '), 0xFF60A8FF)
    else
        setStatus('Черновик собран. Проверьте результат и нажмите «Проверить».', 0xFF79D8A2)
    end
end

local function addFinding(level, text)
    findings[#findings + 1] = { level = level, text = text }
end

local function checkDraft()
    local text = readBuffer(output):gsub('^%s*(.-)%s*$', '%1')
    if text == '' then
        findings = {}
        addFinding('Информация', 'Сначала соберите черновик или введите текст вручную.')
        setStatus('Нет текста для проверки.', 0xFF60A8FF)
        return
    end

    local cp = u8:decode(text)
    local lower = cpLower(cp)
    local template = templates[selectedTemplate]
    findings = {}

    local first
    for i = 1, #cp do
        local b = cp:byte(i)
        if (b >= 65 and b <= 90) or (b >= 97 and b <= 122)
            or (b >= 192 and b <= 223) or (b >= 224 and b <= 255)
            or b == 168 or b == 184 then
            first = cp:sub(i, i)
            break
        end
    end
    if first then
        local b = first:byte(1)
        if (b >= 97 and b <= 122) or (b >= 224 and b <= 255) or b == 184 then
            addFinding('Ошибка', 'Первая буква строчная. По п. 1.1 начало должно быть с заглавной.')
        else
            addFinding('Проверено', 'Начальная буква выглядит заглавной (п. 1.1).')
        end
    end

    local kkPattern = '%d[%d%s%.,]*%s*' .. toCp('[kк][kк]')
    local oooPattern = '%d[%d%s%.,]*%s*' .. toCp('[oо][oо][oо]')
    if lower:find(kkPattern) or lower:find(oooPattern) then
        addFinding('Ошибка', 'Возможный формат цены kk/OOO. Укажите цену понятным форматом (п. 1.5).')
    else
        addFinding('Проверка вручную', 'Сверьте цену и единицы измерения с п. 1.5.')
    end

    if hasAny(lower, { 'telegram', 'телеграм', 'discord', 'дискорд' }) or lower:find('%(%(%s*/radio') then
        addFinding('Ошибка', 'Найдена явная OOC-информация или смешение чатов (п. 1.7).')
    else
        addFinding('Проверено', 'Явные маркеры Telegram/Discord не найдены (п. 1.7).')
    end

    if hasAny(lower, { 'кредит', 'займ', 'передача денег', 'передам деньги', 'деньги в долг', 'одолжу деньги' }) then
        addFinding('Проверка вручную', 'Возможна финансово-кредитная операция. Сверьте смысл с запретом §2.2; совпадение слов само по себе не доказывает нарушение.')
    end

    local hasAdAction = hasAny(lower, { 'куплю', 'продам', 'обменяю', 'сдам', 'приобрету' })
    local objectTypes = 0
    if hasAny(lower, { 'дом', 'квартир', 'недвижимост' }) then objectTypes = objectTypes + 1 end
    if hasAny(lower, { 'автомобил', 'машин', 'транспорт', 'мотоцикл' }) then objectTypes = objectTypes + 1 end
    if hasAny(lower, { 'аксессуар' }) then objectTypes = objectTypes + 1 end
    if hasAny(lower, { 'бизнес', 'офис' }) then objectTypes = objectTypes + 1 end
    if hasAdAction and objectTypes > 1 then
        addFinding('Проверка вручную', 'Похоже, текст объединяет несколько видов объявлений. Проверьте правило одного объявления (§2.3).')
    end

    if hasAny(lower, { 'чёрный рынок', 'черный рынок', 'антиреклама', 'заказное убийство', 'заказные убийства', 'выкуп' }) then
        addFinding('Проверка вручную', 'Найдена формулировка, которая может относиться к запрещённым объявлениям (§2.4). Нужна оценка контекста.')
    end
    if hasAny(lower, { 'поздравляю', 'с праздником', 'поздравляем' }) then
        addFinding('Проверка вручную', 'Проверьте, не относится ли поздравление к незначительному событию (§2.5); список значимых событий в полученном тексте не задан.')
    end

    if lower:find('fbi', 1, true) or hasAny(lower, { 'федеральное бюро расследований' }) then
        addFinding('Проверка вручную', 'Упомянут FBI. §2.4/§8.3 запрещают упоминание сотрудников, а §6.3 допускает обозначение госорганизации; оцените контекст.')
    end

    if template.category == 'Недвижимость' and hasAny(lower, { 'квартир' }) and hasAny(lower, { 'куплю', 'продам', 'обменяю' }) then
        addFinding('Ошибка', 'Покупка, продажа или обмен квартиры запрещены (п. 4.1).')
    end
    if template.category == 'Недвижимость' and hasAny(lower, { 'класс' }) and not lower:find('%[[sabcdn]%]') then
        addFinding('Проверка вручную', 'Проверьте формат класса дома в квадратных скобках (п. 4.2).')
    end
    if template.category == 'Транспорт' then
        addFinding('Проверка вручную', 'Если указано название транспорта, проверьте латиницу и кавычки «» или "" (п. 3.1). Определить модель по тексту однозначно нельзя.')
    end
    if template.category == 'Транспорт' and hasAny(lower, { 'класс' }) then
        addFinding('Ошибка', 'В объявлении о транспорте слово «класс» писать нельзя (п. 3.3).')
    end
    if template.category == 'ChatBox' then
        if not lower:match('^%s*%[chatbox%]%s*:') then
            addFinding('Ошибка', 'Для ChatBox требуется приставка [ChatBox]: (п. 8.2).')
        else
            addFinding('Проверено', 'Приставка [ChatBox]: присутствует (п. 8.2).')
        end
    end

    addFinding('Важно', 'Не проверены полноценно: сокращения, капс, смысл и завуалированные формулировки, флуд, география, организации, аксессуары, реальные характеристики транспорта и актуальность правил. Сверьте ПРО HOME и контекст вручную.')
    local errors = 0
    for _, finding in ipairs(findings) do if finding.level == 'Ошибка' then errors = errors + 1 end end
    if errors > 0 then setStatus('Найдено замечаний: ' .. errors .. '. Исправьте текст и проверьте снова.', 0xFF7777FF)
    else setStatus('Проверка завершена. Результат всё равно нужно сверить вручную.', 0xFF79D8A2) end
end

local function firstMatch(text, phrases)
    for _, phrase in ipairs(phrases) do
        if text:find(toCp(phrase), 1, true) then return phrase end
    end
    return nil
end

local function checkAir()
    local text = readBuffer(output):gsub('^%s*(.-)%s*$', '%1')
    findings = {}
    if text == '' then
        addFinding('Информация', 'Сначала загрузите реплику из списка или введите текст эфира.')
        setStatus('Нет текста для проверки.', 0xFF60A8FF)
        return
    end
    local cp = toCp(text)
    local lower = cpLower(cp)

    if firstMatch(lower, { 'аукцион' }) then
        addFinding('Ошибка', 'Аукционы в эфире запрещены (п. 3.4, наказание — default ban).')
    end
    local money = firstMatch(lower, { 'сбор средств', 'собираем деньги', 'соберём деньги', 'переведите', 'скиньте', 'пожертвован', 'донат', 'на счёт редакции', 'на наш счёт' })
    if money then
        addFinding('Ошибка', 'Похоже на сбор средств со слушателей: «' .. money .. '» (п. 3.3 и 3.4, default ban).')
    end
    if not firstMatch(lower, { 'аукцион' }) and not money then
        addFinding('Проверено', 'Аукционов и сбора средств не найдено (п. 3.3, 3.4).')
    end

    local geography = {
        { 'комптон', 'Гантон' }, { 'лос-анджелес', 'Лос-Сантос' }, { 'лос анджелес', 'Лос-Сантос' },
        { 'калифорни', 'Сан-Андреас' },
    }
    local geoFound = false
    for _, pair in ipairs(geography) do
        if lower:find(toCp(pair[1]), 1, true) then
            geoFound = true
            addFinding('Ошибка', 'Реальное название «' .. pair[1] .. '» нужно заменить на IC-аналог — ' .. pair[2] .. ' (п. 3.2).')
        end
    end
    if not geoFound then addFinding('Проверено', 'Реальных географических названий из списка правил не найдено (п. 3.2).') end

    local ooc = firstMatch(lower, { 'лвл', 'уровень', 'скилл', 'хп', 'админ', 'fps', 'фпс', 'пинг', 'оос', 'ooc' })
    if ooc then
        addFinding('Проверка вручную', 'Найдено «' .. ooc .. '». Игровая статистика и ООС-термины заменяются IC-определениями (п. 3.2).')
    end
    if firstMatch(lower, { 'telegram', 'телеграм', 'discord', 'дискорд', 'вконтакте' }) then
        addFinding('Проверка вручную', 'Упомянуты внешние ресурсы. ООС-информация допустима только без политики и межнационального контекста (п. 3.2).')
    end
    if firstMatch(lower, { 'розыгрыш', 'приз', 'разыгр' }) then
        addFinding('Проверка вручную', 'Розыгрыш: призы должны быть у редакции и выданы победителям, условия выполнимы, участников нельзя вводить в заблуждение (п. 1.6, 3.1 — ЧС фракции на 5 дней).')
    end

    local latin, cyrillic = 0, 0
    for i = 1, #lower do
        local b = lower:byte(i)
        if b >= 97 and b <= 122 then latin = latin + 1
        elseif b >= 224 or b == 184 then cyrillic = cyrillic + 1 end
    end
    if latin > 8 and latin > (latin + cyrillic) * 0.3 then
        addFinding('Проверка вручную', 'Много латиницы. Язык эфира — русский; исключения — названия транспорта, бизнесов, казино, классов и организаций (п. 1.3).')
    end
    if #cp > 144 then
        addFinding('Проверка вручную', 'Реплика длиннее 144 символов — чат может её обрезать. Разбейте её на две.')
    end

    addFinding('Проверка вручную', 'Мат, вульгарность, оскорбления и антиреклама требуют проверки человеком. Ведущий отвечает за слова гостей и слушателей (п. 1.4, 1.5, 3.5, 3.6 — мут 15–30 минут).')
    addFinding('Важно', 'Это подсказка по тексту, а не гарантия соответствия правилам. Структура эфира (п. 1.2) носит рекомендательный характер.')

    local errors = 0
    for _, finding in ipairs(findings) do if finding.level == 'Ошибка' then errors = errors + 1 end end
    if errors > 0 then setStatus('Найдено замечаний по правилам эфира: ' .. errors .. '.', 0xFF7777FF)
    else setStatus('Проверка эфира завершена. Остальное сверьте вручную.', 0xFF79D8A2) end
end

local function insertDraft()
    local text = profile.apply(readBuffer(output)):gsub('^%s*(.-)%s*$', '%1')
    if text == '' then setStatus('Сначала соберите или введите текст.', 0xFF60A8FF); return false end
    if not sampIsDialogActive() then
        setStatus('Откройте игровое поле ввода объявления, затем нажмите «Вставить» или Alt+3.', 0xFF60A8FF)
        return false
    end
    sampSetCurrentDialogEditboxText(u8:decode(text))
    setStatus('Текст вставлен в активное поле. Проверьте его и отправьте вручную.', 0xFF79D8A2)
    return true
end

local function insertChatDraft(sendInstantly)
    local text = profile.apply(readBuffer(output)):gsub('^%s*(.-)%s*$', '%1')
    if text == '' then setStatus('Сначала соберите или введите текст.', 0xFF60A8FF); return false end
    if not sampIsChatInputActive() then
        if sendInstantly then
            sampSendChat(u8:decode(text))
            setStatus('Текст отправлен в игровой чат по нажатию кнопки.', 0xFF79D8A2)
            return true
        end
        setStatus('Откройте игровой чат (клавиша T) и повторите вставку.', 0xFF60A8FF)
        return false
    end
    if sendInstantly then
        sampSendChat(u8:decode(text))
        setStatus('Текст отправлен в игровой чат по нажатию кнопки.', 0xFF79D8A2)
        return true
    end
    sampSetChatInputText(u8:decode(text))
    setStatus('Текст помещён в строку чата. Проверьте его и отправьте клавишей Enter вручную.', 0xFF79D8A2)
    return true
end

-- Отправка ОДНОЙ реплики викторины только по нажатию кнопки ведущим.
-- После включения прямого эфира через /n обычный чат транслируется на радиоволну.
local function sendQuizDraft()
    local raw=trimText(profile.apply(readBuffer(output)))
    if raw=='' then setStatus('Пустой текст. Сначала выберите реплику.',0xFF60A8FF);return false end
    if raw:find('[\r\n]') then
        setStatus('Реплика содержит перенос строки. Разбейте её на отдельные сообщения.',0xFF7777FF)
        return false
    end
    local ok, cp = pcall(toCp,raw)
    if not ok or type(cp)~='string' then
        setStatus('В тексте есть символы, которые нельзя перевести в кодировку чата CP1251.',0xFF7777FF)
        return false
    end
    if #cp>140 then
        setStatus('Слишком длинная реплика ('..#cp..' байт). Укоротите до 140.',0xFF7777FF)
        return false
    end
    if type(sampSendChat)~='function' then
        setStatus('Не найдена функция отправки SA-MP.',0xFF7777FF);return false
    end
    local sent, err=pcall(sampSendChat,cp)
    if not sent then
        setStatus('Не удалось отправить: '..tostring(err),0xFF7777FF);return false
    end
    quizGame.markSent()
    setStatus('Реплика отправлена по вашему нажатию. Убедитесь, что эфир включён через /n.',0xFF79D8A2)
    return true
end

local function drawInput(key, hint, width)
    local value = inputs[key]
    imgui.SetNextItemWidth(width or -1)
    imgui.InputTextWithHint(u8('##' .. key), u8(hint or ''), value, ffi.sizeof(value))
end

local function chooseTemplate(index)
    selectedTemplate = index
    local action = templates[index].action
    if action ~= '' then writeBuffer(inputs.action, 96, action) end
    findings = {}
end

local function getLocalPlayerPed()
    if type(getPlayerChar) ~= 'function' then return nil end
    local player = type(PLAYER_HANDLE) ~= 'nil' and PLAYER_HANDLE or 0
    local ok, exists, ped = pcall(getPlayerChar, player)
    if ok and exists then return ped end
    return nil
end

local function getLocalWeapon(ped)
    local ok, weapon = pcall(getCurrentCharWeapon, ped)
    if ok then return weapon end
    return nil
end

