            "Отсюда открываются виды на окружающие скалы и водохранилище.",
            "Удивительно, как простое отверстие в камне может превратиться в целую достопримечательность.",
            "Арка будто создаёт рамку для пейзажа: всё то же небо, всё те же холмы, но взгляд становится точнее.",
            "Иногда для нового впечатления не нужно менять мир вокруг. Достаточно выбрать другую точку зрения.",
            "Особенно красиво представить это место в последние минуты перед закатом.",
            "Солнце опускается, краски постепенно становятся мягче, и камень на мгновение кажется тёплым.",
            "В такие часы даже простая остановка у дороги может превратиться в воспоминание на долгие месяцы.",
            "И пока города загораются рекламой и огнями, здесь главную роль исполняют неоновые цвета самого неба.",
            "Вспомните наш сегодняшний путь: смешная фигура у дороги, пустая полоса, огромные скалы, покинутые дома.",
            "Каждое место оказалось непохожим на соседнее, но у всех нашлось кое-что общее.",
            "Каждое предложило нам остановиться и увидеть больше, чем просто название на карте.",
            "Именно ради таких деталей мы и возвращаемся в рубрику «Сан-Андреас за кадром».",
            "Ведь привычная дорога легко становится открытием, если перестать смотреть только на следующую развязку.",
            "…::: Спокойная музыкальная перебивка перед финалом :::…",
            "Наше радиопутешествие подходит к концу. Сегодня мы увидели другую сторону пустынного Сан-Андреаса.",
            "Лас-Паясадас напомнил: улыбку иногда дарит даже самая неожиданная придорожная деталь.",
            "Вердант-Медоуз рассказал историю дороги, которая однажды устремилась прямо в небо.",
            "Скалы Эль-Кастильо-дель-Дьябло показали, насколько впечатляющей бывает работа природы.",
            "А Лас-Брухас заставил задуматься о людях, чьи истории не всегда сохраняются в путеводителях.",
            "Наконец, Арко-дель-Оэсте напомнил простую вещь: иногда весь секрет — в правильном ракурсе.",
            "Самое интересное здесь даже не сами достопримечательности, а вопросы, которые они оставляют после себя.",
            "Кто-то найдёт на такой дороге вдохновение, кто-то — спокойствие, а кто-то — идею для следующей поездки.",
            "И, возможно, именно вы однажды откроете малоизвестное место, о котором захотите рассказать всему штату.",
            "Только помните: впечатления стоят того, чтобы добираться до них без риска для себя и окружающих.",
            "Спасибо, что были с нами. Вы слушали второй выпуск «Сан-Андреас за кадром».",
            "У микрофона был {my_name}. В эфире работала редакция Las Venturas News.",
            "Берегите себя, цените дорогу и до новых встреч на волне 103.3 FM!",
            "…::: Финальная музыкальная заставка Las Venturas News :::…",
        },
        chapters={
            {name="00:00–02:00 · ВСТУПЛЕНИЕ", first=1, last=14},
            {name="02:00–04:35 · ЛАС-ПАЯСАДАС", first=15, last=29},
            {name="04:35–07:40 · ВЕРДАНТ-МЕДОУЗ", first=30, last=48},
            {name="07:40–10:35 · КАСТИЛЬО-ДЕЛЬ-ДЬЯБЛО", first=49, last=66},
            {name="10:35–13:45 · ЛАС-БРУХАС", first=67, last=85},
            {name="13:45–16:20 · АРКО-ДЕЛЬ-ОЭСТЕ", first=86, last=100},
            {name="16:20–18:30 · ФИНАЛ", first=101, last=114},
        },
    },
}
airProgram.episodes=airEpisodes
airProgram.episodeIndex=1

do
    local function prepare(index, saveSelection)
        index=math.max(1,math.min(#airProgram.lines,tonumber(index) or 1))
        airProgram.current=index
        airProgram.preparedIndex=index
        writeBuffer(airProgram.draft,1024,profile.apply(airProgram.lines[index]))
        airProgram.needsScroll=true
        airProgram.resetArmed=false
        if saveSelection and airProgram.save then airProgram.save() end
        return true
    end
    local function folder()
        local f=getGameDirectory()..'\\moonloader\\config\\LVNHelper'
        if not doesDirectoryExist(f) then createDirectory(f) end
        return f
    end
    local function selectData(index)
        index=math.max(1,math.min(#airEpisodes,math.floor(tonumber(index) or 1)))
        local episode=airEpisodes[index]
        airProgram.episodeIndex=index
        airProgram.title=episode.title
        airProgram.lines=episode.lines
        airProgram.chapters=episode.chapters
        airProgram.path=folder()..'\\'..episode.filename
        airProgram.sent={}; airProgram.current=1; airProgram.startedAt=0
        airProgram.resetArmed=false
    end
    local function save()
        if not airProgram.path then return false end
        local data={current=airProgram.current,sent=airProgram.sent,startedAt=airProgram.startedAt}
        local ok,encoded=pcall(encodeJson,data)
        if not ok or type(encoded)~='string' then return false end
        local f=io.open(airProgram.path,'w')
        if not f then return false end
        f:write(encoded);f:close();return true
    end
    local function loadEpisode(index)
        selectData(index)
        if doesFileExist(airProgram.path) then
            local f=io.open(airProgram.path,'r')
            if f then
                local raw=f:read('*a');f:close()
                local ok,stored=pcall(decodeJson,raw)
                if ok and type(stored)=='table' then
                    airProgram.current=math.max(1,math.min(#airProgram.lines,math.floor(tonumber(stored.current) or 1)))
                    if type(stored.sent)=='table' then
                        for i=1,#airProgram.lines do
                            if stored.sent[tostring(i)]==true then airProgram.sent[tostring(i)]=true end
                        end
                    end
                    airProgram.startedAt=tonumber(stored.startedAt) or 0
                end
            end
        end
        prepare(airProgram.current,false)
    end
    local function load()
        local file=folder()..'\\air_episode_selection.json'
        local index=1
        if doesFileExist(file) then
            local f=io.open(file,'r')
            if f then
                local raw=f:read('*a');f:close()
                local ok,stored=pcall(decodeJson,raw)
                if ok and type(stored)=='table' then index=tonumber(stored.index) or 1 end
            end
        end
        loadEpisode(index)
    end
    local function selectEpisode(index)
        index=math.max(1,math.min(#airEpisodes,math.floor(tonumber(index) or 1)))
        if index==airProgram.episodeIndex then return false end
        save() -- сохраняем предыдущий выпуск отдельно
        loadEpisode(index)
        local f=io.open(folder()..'\\air_episode_selection.json','w')
        if f then
            local ok,encoded=pcall(encodeJson,{index=index})
            if ok then f:write(encoded) end
            f:close()
        end
        airProgram.info='Выбран выпуск №'..index..'. Прогресс каждого выпуска сохраняется отдельно.'
        setStatus('Загружен выпуск №'..index..': '..airProgram.title,0xFF79D8A2)
        return true
    end
    local function setSpecial(text)
        writeBuffer(airProgram.draft,1024,profile.apply(text))
        airProgram.preparedIndex=nil
        airProgram.info='Подготовлена отдельная реплика; отправка не изменит ход сценария.'
    end
    local function countSent()
        local n=0
        for i=1,#airProgram.lines do if airProgram.sent[tostring(i)] then n=n+1 end end
        return n
    end
    local function send()
        local text=profile.apply(readBuffer(airProgram.draft)):gsub('^%s*(.-)%s*$','%1')
        if text=='' then setStatus('Сначала выберите реплику или введите текст.',0xFF60A8FF);return false end
        local cp=toCp(text)
        if #cp>140 then
            setStatus('Реплика длиннее 140 байт в CP1251 ('..#cp..'). Сократите текст.',0xFF7777FF)
            return false
        end
        if type(sampSendChat)~='function' then setStatus('Нет функции sampSendChat.',0xFF7777FF);return false end
        local ok,err=pcall(sampSendChat,cp)
        if not ok then setStatus('Ошибка отправки: '..tostring(err),0xFF7777FF);return false end
        if airProgram.startedAt==0 then airProgram.startedAt=os.time() end
        local index=airProgram.preparedIndex
        if index and airProgram.lines[index] then
            airProgram.sent[tostring(index)]=true
            if index<#airProgram.lines then prepare(index+1,false) end
            airProgram.info=('Реплика %03d отправлена. Следующая подготовлена.'):format(index)
        else
            airProgram.info='Дополнительная реплика отправлена.'
        end
        save()
        setStatus('Текст отправлен по нажатию кнопки. Убедитесь, что эфир включён через /n.',0xFF79D8A2)
        return true
    end
    local function putInChat()
        local text=profile.apply(readBuffer(airProgram.draft)):gsub('^%s*(.-)%s*$','%1')
        if text=='' then setStatus('Нет подготовленной реплики.',0xFF60A8FF);return false end
        if #toCp(text)>140 then setStatus('Сократите текст до 140 байт.',0xFF7777FF);return false end
        if not sampIsChatInputActive() then
            setStatus('Откройте строку чата клавишей T и нажмите «В строку чата».',0xFF60A8FF)
            return false
        end
        sampSetChatInputText(toCp(text))
        setStatus('Текст вставлен в строку чата. Отправьте его Enter, затем отметьте шаг выполненным.',0xFF79D8A2)
        return true
    end
    local function markDone()
        local index=airProgram.preparedIndex
        if not index then
            setStatus('Сначала выберите номер шага из сценария.',0xFF60A8FF);return false end
        airProgram.sent[tostring(index)]=true
        if airProgram.startedAt==0 then airProgram.startedAt=os.time() end
        if index<#airProgram.lines then prepare(index+1,false) end
        save()
        setStatus(('Реплика %03d отмечена как выполненная.'):format(index),0xFF79D8A2)
        return true
    end
    local function reset()
        if not airProgram.resetArmed then
            airProgram.resetArmed=true
            airProgram.info='Для сброса прогресса нажмите кнопку «Сбросить прогресс» ещё раз.'
            return false
        end
        airProgram.sent={};airProgram.startedAt=0
        prepare(1,false)
        airProgram.info='Прогресс сценария очищен. Начинайте с первой реплики.'
        save();return true
    end
    airProgram.save=save
    airProgram.load=load
    airProgram.selectEpisode=selectEpisode
    airProgram.prepare=prepare
    airProgram.setSpecial=setSpecial
    airProgram.countSent=countSent
    airProgram.send=send
    airProgram.putInChat=putInChat
    airProgram.markDone=markDone
    airProgram.reset=reset
end

function main()
    if type(isSampAvailable) ~= 'function' or type(sampRegisterChatCommand) ~= 'function' then
        print('[LVN Helper] Не найден SAMPFUNCS: функции sampXXX недоступны, скрипт выгружен.')
        thisScript():unload()
        return
    end
    while not isSampAvailable() do wait(100) end
    sampRegisterChatCommand('lvn', function() opened[0] = not opened[0] end)
    local settingsOk, settingsError = pcall(loadFavorites)
    if not settingsOk then
        print('[LVN Helper] Не удалось загрузить настройки: ' .. tostring(settingsError))
    end
    profile.suggest()
    -- Не запускаем старые фоновые режимы из сохранённых настроек.
    rememberAdEdits[0]=false; dndMode[0]=false; autoGreeting[0]=false
    showSmsLogger[0]=false
    autoCameraRP[0]=false; rankTagBinder[0]=false; isBroadcastActive[0]=false
    pcall(quizGame.load)
    local airOk,airError=pcall(airProgram.load)
    if not airOk then print("[LVN Helper] Ошибка загрузки сценария: "..tostring(airError)) end
    local bindsOk, bindsError = pcall(loadBinds)
    if not bindsOk then
        print('[LVN Helper] Не удалось загрузить отыгровки: ' .. tostring(bindsError))
        bindGroups = presetBindGroups()
    end
    local ped = getLocalPlayerPed()
    if ped then lastWeapon = getLocalWeapon(ped) or 0 end
    sampAddChatMessage(u8:decode('{A78BFA}[LVN Helper] {FFFFFF}Открыть помощник: {A78BFA}/lvn{FFFFFF}. Вставка текста настраивается в «Настройках».'), -1)
    while true do
        wait(0)
        local modifierKey = availableModifiers[selectedModifier[0] + 1].key
        local triggerKey = availableKeys[selectedKey[0] + 1].key
        if not opened[0] and wasKeyPressed(triggerKey) and isKeyDown(modifierKey) then
            if sampIsDialogActive() then insertDraft()
            elseif sampIsChatInputActive() then insertChatDraft()
            else setStatus('Откройте строку чата или игровой диалог и нажмите выбранную комбинацию.', 0xFF60A8FF) end
        end

        if isBroadcastActive[0] and wasKeyPressed(keys.VK_ADD) and isKeyDown(keys.VK_MENU) then
            local stage = mediaModes[selectedMediaMode].stages[currentBroadcastStage]
            if stage then
                selectMediaStage(stage)
                sampSendChat(u8:decode(profile.apply(readBuffer(output))))
                setStatus('Этап отыгровки отправлен. Следующий: Alt+Numpad+.', 0xFF79D8A2)
                currentBroadcastStage = currentBroadcastStage + 1
            else
                isBroadcastActive[0] = false
                currentBroadcastStage = 1
                setStatus('Этапы набора завершены; биндер остановлен.', 0xFF60A8FF)
            end
        end

        ped = getLocalPlayerPed()
        if ped then
            local weapon = getLocalWeapon(ped)
            if weapon and autoCameraRP[0] and weapon ~= lastWeapon then
                if weapon == 43 then
                    lua_thread.create(function()
                        sampSendChat(u8:decode(effectiveCommand(doCommand, '/do') .. ' На шее висит фотоаппарат.'))
                        wait(1500)
                        sampSendChat(u8:decode(effectiveCommand(meCommand, '/me') .. ' снимает крышку с объектива и берёт фотоаппарат в руки'))
                        wait(1500)
                        sampSendChat(u8:decode(effectiveCommand(doCommand, '/do') .. ' Фотоаппарат готов к съёмке.'))
                    end)
                elseif lastWeapon == 43 then
                    lua_thread.create(function()
                        sampSendChat(u8:decode(effectiveCommand(meCommand, '/me') .. ' надевает крышку на объектив и вешает фотоаппарат на шею'))
                    end)
                end
            end
            if weapon then lastWeapon = weapon end
        end
    end
end

-- ════════════════════════════════════════════════════════════════
--  ИНТЕРФЕЙС
--  Левое меню + рабочая область + строка состояния.
--  Все размеры идут через S(): масштаб считается от высоты экрана.
-- ════════════════════════════════════════════════════════════════
local V2, V4 = imgui.ImVec2, imgui.ImVec4
local uiScale = 1.0
local fontMain, fontTitle, fontRanges
local currentSection = 1

local airChecklistItems = {
    'Пиар-объявление чётко отражает тему эфира (п. 1.1)',
    'Призы розыгрыша есть у редакции и будут выданы победителям (п. 1.6, 3.1)',
    'Реальные города и игровая статистика заменены на IC-аналоги (п. 3.2)',
    'В эфире не будет сбора средств и аукционов (п. 3.3, 3.4)',
    'Я отвечаю за слова гостей и слушателей, мат и оскорбления исключены (п. 1.4, 1.5)',
    'SMS и звонки слушателей принимает сотрудник с 5-го ранга (п. 2.2)',
}
local airChecklist = {}
for i = 1, #airChecklistItems do airChecklist[i] = imgui.new.bool(false) end

local function S(value) return math.floor(value * uiScale + 0.5) end

local C = {
    bg        = V4(0.047, 0.055, 0.078, 0.985),
    side      = V4(0.030, 0.036, 0.056, 1.00),
    line      = V4(0.17, 0.19, 0.27, 0.75),
    text      = V4(0.91, 0.93, 0.97, 1.00),
    muted     = V4(0.56, 0.61, 0.72, 1.00),
    frame     = V4(0.115, 0.130, 0.180, 1.00),
    neutral   = V4(0.165, 0.185, 0.265, 1.00),
    neutralHi = V4(0.225, 0.245, 0.355, 1.00),
    neutralLo = V4(0.290, 0.300, 0.440, 1.00),
    accent    = V4(0.58, 0.42, 0.98, 1.00),
    accentHi  = V4(0.70, 0.57, 1.00, 1.00),
    accentLo  = V4(0.38, 0.27, 0.66, 1.00),
    ok        = V4(0.47, 0.85, 0.64, 1.00),
    warn      = V4(1.00, 0.70, 0.34, 1.00),
    bad       = V4(1.00, 0.42, 0.45, 1.00),
    info      = V4(0.55, 0.72, 1.00, 1.00),
    live      = V4(1.00, 0.27, 0.33, 1.00),
    white     = V4(1, 1, 1, 1),
    clear     = V4(0, 0, 0, 0),
}

local buttonKinds = {
    primary = { C.accent, C.accentHi, C.accentLo },
    danger  = { V4(0.55, 0.20, 0.25, 1), V4(0.72, 0.26, 0.32, 1), V4(0.45, 0.15, 0.20, 1) },
    warn    = { V4(0.60, 0.38, 0.13, 1), V4(0.78, 0.52, 0.20, 1), V4(0.48, 0.30, 0.10, 1) },
}

local findingColors = {
    ['Ошибка'] = C.bad,
    ['Проверено'] = C.ok,
    ['Проверка вручную'] = C.warn,
    ['Важно'] = C.info,
    ['Информация'] = C.info,
}

-- ── Мелкие помощники ─────────────────────────────────────────────
local function spacing(h) imgui.Dummy(V2(0, S(h or 6))) end

local function splitW(parts)
    local width = imgui.GetContentRegionAvail().x
    local gap = imgui.GetStyle().ItemSpacing.x
    return math.floor((width - gap * (parts - 1)) / parts)
end

local function muted(text)
    imgui.PushStyleColor(imgui.Col.Text, C.muted)
    imgui.TextWrapped(u8(text))
    imgui.PopStyleColor()
end

local function bullet(text)
    imgui.Bullet()
    imgui.SameLine()
    imgui.TextWrapped(u8(text))
end

local function sectionLabel(text)
    spacing(8)
    imgui.TextColored(C.accentHi, u8(text))
    imgui.Separator()
    spacing(3)
end

local function styledButton(text, width, height, kind)
    local scheme = kind and buttonKinds[kind]
    if scheme then
        imgui.PushStyleColor(imgui.Col.Button, scheme[1])
        imgui.PushStyleColor(imgui.Col.ButtonHovered, scheme[2])
        imgui.PushStyleColor(imgui.Col.ButtonActive, scheme[3])
    end
    local clicked = imgui.Button(u8(text), V2(width or 0, height or S(34)))
    if scheme then imgui.PopStyleColor(3) end
    return clicked
end

local function tooltip(text)
    if imgui.IsItemHovered() then imgui.SetTooltip(u8(text)) end
end

-- Цветная точка перед строкой текста.
local function dot(color)
    local pos = imgui.GetCursorScreenPos()
    local radius = S(4)
    local lineHeight = imgui.GetTextLineHeight()
    imgui.GetWindowDrawList():AddCircleFilled(
        V2(pos.x + radius, pos.y + lineHeight / 2), radius, imgui.GetColorU32Vec4(color), 12)
    imgui.Dummy(V2(radius * 2, lineHeight))
    imgui.SameLine(0, S(8))
end

-- Переключатель вместо квадратного чекбокса. state — imgui.new.bool.
local function switch(id, state)
    local width, height = S(40), S(22)
    local pos = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton('##sw_' .. id, V2(width, height))
    if clicked then state[0] = not state[0] end
    local hovered = imgui.IsItemHovered()
    local track
    if state[0] then track = hovered and C.accentHi or C.accent
    else track = hovered and C.neutralHi or C.neutral end
    local list = imgui.GetWindowDrawList()
    list:AddRectFilled(pos, V2(pos.x + width, pos.y + height), imgui.GetColorU32Vec4(track), height / 2)
    local knobX = state[0] and (pos.x + width - height / 2) or (pos.x + height / 2)
    list:AddCircleFilled(V2(knobX, pos.y + height / 2), height / 2 - S(3), imgui.GetColorU32Vec4(C.white), 20)
    return clicked
end

-- Строка настройки: переключатель, название и пояснение.
local function switchRow(id, title, description, state)
    local clicked = switch(id, state)
    imgui.SameLine(0, S(12))
    imgui.BeginGroup()
    imgui.Text(u8(title))
    if description and description ~= '' then muted(description) end
    imgui.EndGroup()
    spacing(6)
    return clicked
end

local function autoSave()
    if persistSettings() then setStatus('Настройка сохранена.', 0xFF79D8A2)
    else setStatus('Не удалось сохранить настройки. Проверьте доступ к папке MoonLoader.', 0xFF7777FF) end
end

local sections
do -- разделы окна лежат в do-блоке: так не упираемся в лимит 200 локальных переменных
-- ── Раздел: Объявления ───────────────────────────────────────────
local function drawFindings()
    if #findings == 0 then return end
    local errors, manual, passed = 0, 0, 0
    for _, finding in ipairs(findings) do
        if finding.level == 'Ошибка' then errors = errors + 1
        elseif finding.level == 'Проверка вручную' then manual = manual + 1
        elseif finding.level == 'Проверено' then passed = passed + 1 end
    end
    sectionLabel('Результат проверки')
    imgui.TextColored(errors > 0 and C.bad or C.ok,
        u8(string.format('Ошибок: %d  ·  Проверить вручную: %d  ·  В порядке: %d', errors, manual, passed)))
    spacing(4)
    for _, finding in ipairs(findings) do
        imgui.TextColored(findingColors[finding.level] or C.muted, u8(finding.level))
        imgui.SameLine(S(160))
        imgui.TextWrapped(u8(finding.text))
        spacing(3)
    end
end

local function drawAds()
    local hotkey = availableModifiers[selectedModifier[0] + 1].name .. '+' .. availableKeys[selectedKey[0] + 1].name
    muted('Выберите шаблон, заполните поля и соберите текст. Вставка в чат или диалог — кнопками ниже или сочетанием ' .. hotkey .. '.')

    sectionLabel('Шаблон')
    local perRow = 3
    local width = splitW(perRow)
    for i, template in ipairs(templates) do
        if (i - 1) % perRow ~= 0 then imgui.SameLine() end
        if styledButton(template.name .. '##tpl' .. i, width, S(34), i == selectedTemplate and 'primary' or nil) then
            chooseTemplate(i)
        end
    end

    sectionLabel('Поля')
    local needed = {}
    for key in templates[selectedTemplate].body:gmatch('{([%w_]+)}') do needed[key] = true end
    imgui.Columns(2, '##ad_fields', false)
    for _, item in ipairs(fields) do
        if needed[item[1]] then
            imgui.TextColored(C.muted, u8(item[2]))
            drawInput(item[1], '')
            spacing(4)
            imgui.NextColumn()
        end
    end
    imgui.Columns(1)

    spacing(4)
    local third = splitW(3)
    if styledButton('Собрать черновик', third, S(38), 'primary') then compose() end
    imgui.SameLine()
    if styledButton('Проверить по ПРО', third, S(38)) then checkDraft() end
    imgui.SameLine()
    if styledButton('В избранное', third, S(38)) then saveFavorite() end

    sectionLabel('Готовый текст')
    imgui.InputTextMultiline('##output', output, 4096, V2(-1, S(92)))
    local half = splitW(2)
    if styledButton('Вставить в строку чата', half, S(36)) then insertChatDraft() end
    imgui.SameLine()
    if styledButton('Вставить в диалог объявления', half, S(36)) then insertDraft() end
    spacing(2)
    imgui.TextDisabled(u8'Скрипт не отправляет объявление за вас — только подставляет текст.')

    drawFindings()
    spacing(8)
end

-- ── Раздел: Избранное ────────────────────────────────────────────
local function drawFavorites()
    muted('Сохранённые черновики остаются на этом компьютере между запусками игры (до 40 штук).')
    spacing(6)
    if #favorites == 0 then
        imgui.Text(u8'Здесь пока пусто.')
        muted('Соберите объявление или выберите слоган и нажмите «В избранное».')
        return
    end

    imgui.BeginChild('##fav_list', V2(-1, S(230)), true)
    for i, favorite in ipairs(favorites) do
        local title = string.format('%02d   %s##fav%d', i, favorite.name or 'Черновик', i)
        if imgui.Selectable(u8(title), selectedFavorite == i) then selectedFavorite = i end
    end
    imgui.EndChild()

    local favorite = favorites[selectedFavorite]
    if not favorite then
        spacing(4)
        muted('Выберите черновик из списка.')
        return
    end

    sectionLabel('Выбранный текст')
    imgui.TextWrapped(u8(favorite.text or ''))
    spacing(8)
    local quarter = splitW(4)
    if styledButton('В черновик', quarter, S(36), 'primary') then
        writeBuffer(output, 4096, favorite.text or '')
        findings = {}
        setStatus('Черновик загружен из избранного.', 0xFF79D8A2)
    end
    imgui.SameLine()
    if styledButton('В строку чата', quarter, S(36)) then
        writeBuffer(output, 4096, favorite.text or '')
        insertChatDraft()
    end
    imgui.SameLine()
    if styledButton('В диалог', quarter, S(36)) then
        writeBuffer(output, 4096, favorite.text or '')
        insertDraft()
    end
    imgui.SameLine()
    if styledButton('Удалить', quarter, S(36), 'danger') then
        deleteFavorite(selectedFavorite)
        setStatus('Черновик удалён из избранного.', 0xFF60A8FF)
    end
end

-- ── Раздел: Слоганы ──────────────────────────────────────────────
local function drawSlogans()
    muted('322 рекламных слогана из темы LV News + 50 фактов из прежней библиотеки. Сведения о скидках, GPS и вакансиях проверяйте перед отправкой.')
    imgui.TextDisabled(u8'Источник: samp-rp.su/threads/lv-news-reklamnye-slogany-organizacij-piar-biznesov.2660559/')
    spacing(6)
    if styledButton('СТО LS', S(100), S(32)) then
        for i, group in ipairs(sloganGroups) do
            if group.name == 'СТО Los Santos' then selectedSloganCategory[0] = i; selectedSlogan = 1; break end
        end
    end
    imgui.SameLine()
    if styledButton('Ферма №3', S(110), S(32)) then
        for i, group in ipairs(sloganGroups) do
            if group.name == 'Ферма №3' then selectedSloganCategory[0] = i; selectedSlogan = 1; break end
        end
    end
    imgui.SameLine()
    if styledButton('Эфиры', S(100), S(32)) then
        for i, group in ipairs(sloganGroups) do
            if group.name == 'Эфиры и мероприятия LV News' then selectedSloganCategory[0] = i; selectedSlogan = 1; break end
        end
    end
    imgui.SameLine()
    imgui.SetNextItemWidth(S(145))
    imgui.InputTextWithHint('##slogan_farm_number', u8'№ фермы: 3', sloganFarmNumber, 8)

    local activeCategoryName = sloganCategoryNames[selectedSloganCategory[0] + 1] or sloganCategoryNames[1]
    imgui.SetNextItemWidth(S(250))
    if imgui.BeginCombo('##slogan_category', u8(activeCategoryName)) then
        for i, categoryName in ipairs(sloganCategoryNames) do
            local categoryIndex = i - 1
            if imgui.Selectable(u8(categoryName), selectedSloganCategory[0] == categoryIndex) then
                selectedSloganCategory[0] = categoryIndex
                selectedSlogan = 1
            end
        end
        imgui.EndCombo()
    end
    imgui.SameLine()
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##slogan_search', u8'Поиск по слогану или организации', sloganSearch, 256)

    local rows = currentSloganRows()
    local needle = cpLower(u8:decode(readBuffer(sloganSearch)))
    local visibleRows = {}
    for i, row in ipairs(rows) do
        local phrase = row.text or row
        local categoryName = row.category or activeCategoryName
        local searchText = cpLower(u8:decode(categoryName .. ' ' .. phrase))
        if needle == '' or searchText:find(needle, 1, true) then
            visibleRows[#visibleRows + 1] = { index = i, text = phrase, category = categoryName }
        end
    end
    local selectedVisible = false
    for _, entry in ipairs(visibleRows) do
        if entry.index == selectedSlogan then selectedVisible = true; break end
    end
    if not selectedVisible and visibleRows[1] then selectedSlogan = visibleRows[1].index end

    spacing(2)
    imgui.TextDisabled(u8(string.format('Найдено: %d из %d', #visibleRows, #rows)))
    local listHeight = math.max(S(150), imgui.GetContentRegionAvail().y - S(150))
    imgui.BeginChild('##slogan_results', V2(-1, listHeight), true)
    for _, entry in ipairs(visibleRows) do
        local label = entry.text
        if selectedSloganCategory[0] == 0 then label = '[' .. entry.category .. '] ' .. label end
        if imgui.Selectable(u8(label .. '##slogan_' .. entry.index), selectedSlogan == entry.index) then
            selectedSlogan = entry.index
        end
    end
    if #visibleRows == 0 then imgui.TextDisabled(u8'По этому запросу ничего не найдено.') end
    imgui.EndChild()

    local selectedRow = rows[selectedSlogan]
    if not selectedRow then return end
    local selectedText = selectedRow.text or selectedRow
    local selectedGroup = selectedRow.category or activeCategoryName
    spacing(4)
    imgui.TextColored(C.accentHi, u8(selectedGroup))
    local farmNumber = readBuffer(sloganFarmNumber):gsub('%D', '')
    if farmNumber == '' then farmNumber = '3' end
    local previewText = selectedText:gsub('№%*', '№' .. farmNumber)
    imgui.TextWrapped(u8(previewText))
    local displayLength = #u8:decode(previewText)
    imgui.TextDisabled(u8(string.format('Длина: %d символов (ориентир: до 80).', displayLength)))
    if displayLength > 80 then muted('Текст длиннее 80 символов: проверьте лимит выбранного способа публикации.') end
    spacing(6)
    local fifth = splitW(5)
    if styledButton('В черновик', fifth, S(36), 'primary') then loadSelectedSlogan() end
    imgui.SameLine()
    if styledButton('В избранное', fifth, S(36)) then
        loadSelectedSlogan()
        saveFavorite('Слоган · ' .. selectedGroup)
    end
    imgui.SameLine()
    if styledButton('В строку чата', fifth, S(36)) then
        loadSelectedSlogan()
        insertChatDraft()
    end
    imgui.SameLine()
    if styledButton('В диалог', fifth, S(36)) then
        loadSelectedSlogan()
        insertDraft()
    end
    imgui.SameLine()
    if styledButton('Отправить в чат', fifth, S(36), 'warn') then
        loadSelectedSlogan()
        insertChatDraft(true)
    end
    tooltip('Отправит слоган в игровой чат сразу, без подтверждения.')
    spacing(8)
end

-- ── Раздел: Конкурс LVN · «Битва умов» ────────────────────────────
local quizUi={
    nickname=buf(64),answer=buf(160),customQuestion=buf(512),
    customAnswer=buf(256),customHint=buf(256),search=buf(128),
    category=1,synced=false,phraseGroup=1,phraseSelected=1,
    difficulty=1, hideUsed=imgui.new.bool(false),
}
local function drawQuiz()
    local st=quizGame.state
    local bank=quizGame.bank
    if not quizUi.synced then
        writeBuffer(quizUi.customQuestion,512,st.customQuestion or '')
        writeBuffer(quizUi.customAnswer,256,st.customAnswer or '')
        writeBuffer(quizUi.customHint,256,st.customHint or '')
        quizUi.synced=true
    end

    imgui.TextColored(C.accentHi,u8'РАДИОСТУДИЯ · 103.3FM · ПРИЗ 250 000 ВИРТ')
    muted('Один экран: выбирайте вопросы, отправляйте реплики, вручную записывайте первого верного участника. Конкурс не читает SMS.')
    local started='не запущен'
    if st.startedAt and st.startedAt>0 then
        local sec=math.max(0,os.time()-st.startedAt)
        started=string.format('%02d:%02d',math.floor(sec/60),sec%60)
    end
    local phase=quizGame.championshipPhase()
    imgui.TextColored(C.info,u8('Раунд '..st.round..(st.championshipMode and (st.round>25 and ' · тай-брейк' or '/25') or '')..'  |  Эфир: '..started..'  |  Цель: 15–20 мин'))
    imgui.SameLine()
    if styledButton(st.startedAt>0 and 'Сбросить таймер' or 'Старт 20 мин',S(160),S(27)) then
        if st.startedAt>0 then st.startedAt=0 else st.startedAt=os.time() end
        quizGame.save()
    end

    sectionLabel('Чемпионат · 25 раундов')
    if styledButton(st.championshipMode and 'Чемпионат: ВКЛ' or 'Включить чемпионат',S(230),S(34),'primary') then
        quizGame.toggleChampionship()
    end
    imgui.SameLine()
    imgui.TextColored(C.muted,u8('10 лёгких → 7 средних → 8 сложных'))
    if st.championshipMode then
        local phaseText=phase and phase.name or 'Основные раунды завершены'
        local phaseLevel=phase and quizGame.difficultyNames[phase.level] or '—'
        imgui.TextColored(C.accentHi,u8('Сейчас: '..phaseText..' · '..phaseLevel..' · раунд '..st.round))
        local completed=math.min(25,math.max(0,st.round-1+(st.questionSent and 1 or 0)))
        imgui.ProgressBar(completed/25,V2(-1,S(23)),u8('Пройдено раундов: '..completed..' / 25'))
        if styledButton('Реплика текущего этапа',S(235),S(30)) then quizGame.preparePhase() end
        if st.round>=25 then
            imgui.SameLine()
            if styledButton('Решающий вопрос при ничьей',S(245),S(30),'warn') then quizGame.startTiebreak() end
        end
        muted('Уровень вопросов подбирается по текущему этапу, но сам вопрос выбирает ведущий. После 25-го раунда — итог или тай-брейк.')
    else
        muted('Свободная викторина: выбирайте любую сложность. Перейдите в чемпионат для фиксированной сетки 10/7/8.')
    end

    sectionLabel('01 · Сценарий начала — по порядку')
    muted('Ведите сверху вниз: №, когда говорить, текст. Любой шаг можно открыть и отредактировать; отметка ✓ ставится после отправки.')
    local nextStart=nil
    for i=1,#quizGame.startSteps do
        if not st.startDone[tostring(i)] then nextStart=i;break end
    end
    if nextStart then
        imgui.TextColored(C.info,u8(string.format('Следующий шаг: %02d. %s',nextStart,quizGame.startSteps[nextStart].name)))
        if styledButton('Следующий шаг: в черновик##nextstart',S(235),S(30),'primary') then
            quizGame.prepareStep('start',nextStart)
        end
        imgui.SameLine()
        if styledButton('Отправить следующий шаг##nextsend',S(230),S(30)) then
            if quizGame.prepareStep('start',nextStart) then sendQuizDraft() end
        end
    else
        imgui.TextColored(C.ok,u8'Все шаги вступления отправлены.')
    end
    if imgui.CollapsingHeader(u8'Полный пронумерованный список начала (8 шагов)##quizstart') then
        for i,step in ipairs(quizGame.startSteps) do
            local completed=st.startDone[tostring(i)]==true
            imgui.TextColored(completed and C.ok or C.accentHi,u8(string.format('%02d. %s%s',i,step.name,completed and '  [OK]' or '')))
            muted('Когда: '..step.when)
            imgui.TextWrapped(u8(quizGame.phraseText(step.text)))
            if styledButton('В черновик##start'..i,S(155),S(29),'primary') then quizGame.prepareStep('start',i) end
            imgui.SameLine()
            if styledButton('Отправить шаг##startsend'..i,S(165),S(29)) then
                if quizGame.prepareStep('start',i) then sendQuizDraft() end
            end
            imgui.Separator()
        end
    end

    sectionLabel('02 · Готовые реплики ведущего')
    if imgui.CollapsingHeader(u8'Открыть библиотеку реплик (31 фраза)##quizphrases') then
    imgui.SetNextItemWidth(S(210))
    local groups=quizGame.phraseGroups
    if imgui.BeginCombo('##quiz_phrasegroup',u8(groups[quizUi.phraseGroup])) then
        for i,g in ipairs(groups) do
            if imgui.Selectable(u8(g..'##phrasegr'..i),quizUi.phraseGroup==i) then quizUi.phraseGroup=i end
        end
        imgui.EndCombo()
    end
    imgui.BeginChild('##quiz_phrasebank',V2(-1,S(130)),true)
    for i,entry in ipairs(quizGame.phraseLibrary) do
        if quizUi.phraseGroup==1 or entry.group==groups[quizUi.phraseGroup] then
            local selected=quizUi.phraseSelected==i
            if imgui.Selectable(u8(entry.group..' · '..entry.name..'###phrase'..i),selected) then
                quizUi.phraseSelected=i
                quizGame.preparePhrase(i)
            end
        end
    end
    imgui.EndChild()
    if styledButton('Подготовить выбранную реплику##qphrase',S(270),S(31),'primary') then
        quizGame.preparePhrase(quizUi.phraseSelected)
    end
    muted('Реплика загружается в пульт внизу. При необходимости исправьте формулировку.')
    end

    sectionLabel('Музыкальные заставки')
    local music=quizGame.music
    local third=splitW(3)
    for i,entry in ipairs(music) do
        if i>1 and (i-1)%3~=0 then imgui.SameLine() end
        if styledButton(entry.name..'##music'..i,third,S(32)) then quizGame.musicSelect(i) end
    end
    muted('Заставки — текстовые радиоотыгровки для чата.')

    sectionLabel('Выберите вопрос сами')
    local cats=quizGame.categories
    imgui.SetNextItemWidth(S(185))
    if imgui.BeginCombo('##quiz_category',u8(cats[quizUi.category])) then
        for i,cat in ipairs(cats) do
            if imgui.Selectable(u8(cat..'##cat'..i),i==quizUi.category) then quizUi.category=i end
        end
        imgui.EndCombo()
    end
    imgui.SameLine()
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##quiz_search',u8'Поиск по вопросам, например «Франции»',quizUi.search,128)
    imgui.SetNextItemWidth(S(210))
    local dl=quizGame.difficultyNames
    local requiredLevel=quizGame.championshipStage()
    if st.championshipMode and requiredLevel then quizUi.difficulty=requiredLevel+1 end
    local currentDiff=quizUi.difficulty==1 and 'Любая сложность' or dl[quizUi.difficulty-1]
    if imgui.BeginCombo('##quiz_difficulty',u8(currentDiff)) then
        if not st.championshipMode then
            if imgui.Selectable(u8'Все уровни##diffall',quizUi.difficulty==1) then quizUi.difficulty=1 end
        end
        for i,name in ipairs(dl) do
            if (not st.championshipMode or requiredLevel==i)
                and imgui.Selectable(u8(name..'##level'..i),quizUi.difficulty==i+1) then quizUi.difficulty=i+1 end
        end
        imgui.EndCombo()
    end
    imgui.SameLine()
    imgui.Checkbox(u8'Скрыть уже заданные',quizUi.hideUsed)
    imgui.SameLine()
    if styledButton('Случайный неиспользованный##quizrandom',S(235),S(29)) then
        quizGame.selectSurprise(quizUi.difficulty==1 and 0 or quizUi.difficulty-1,cats[quizUi.category])
    end
    local needle=readBuffer(quizUi.search)
    local lowerNeedle=cpLower(toCp(needle))
    imgui.BeginChild('##quiz_questionbank',V2(-1,S(154)),true)
    local shown=0
    for i,q in ipairs(bank) do
        local isCat=quizUi.category==1 or cats[quizUi.category]==q.kind
        local match=lowerNeedle=='' or cpLower(toCp(q.question..' '..q.answer)):find(lowerNeedle,1,true)~=nil
        if isCat and match and (quizUi.difficulty==1 or q.level==quizUi.difficulty-1)
            and (not quizUi.hideUsed[0] or not st.used[tostring(i)]) then
            shown=shown+1
            local mark=st.used[tostring(i)] and '[был] ' or ''
            local label=mark..'['..quizGame.difficultyNames[q.level]..'] '..q.kind..' · '..q.question..'###bank'..i
            local selected=st.mode=='bank' and st.selected==i
            if imgui.Selectable(u8(label),selected) then quizGame.choose(i) end
        end
    end
    if shown==0 then imgui.TextDisabled(u8'Поиск не дал результатов.') end
    imgui.EndChild()
    imgui.TextDisabled(u8('Показано вопросов: '..shown..' / '..#bank))
    local q=quizGame.question()
    if q then
        imgui.TextColored(C.accentHi,u8(quizGame.difficultyNames[q.level or 2]..' · '..q.kind..' · '..q.question))
        imgui.TextColored(C.ok,u8('Правильный ответ: '..(q.answer or '')))
        if q.hint and q.hint~='' then imgui.TextColored(C.muted,u8('Подсказка ведущему: '..q.hint)) end
    else
        imgui.TextColored(C.warn,u8'Вопрос пока не выбран. Выберите его из списка ниже или создайте свой.')
    end

    if imgui.CollapsingHeader(u8'Свой вопрос (можно придумать прямо в эфире)') then
        imgui.InputTextWithHint('##quiz_custom_q',u8'Текст вопроса',quizUi.customQuestion,512)
        imgui.InputTextWithHint('##quiz_custom_a',u8'Правильный ответ (для ведущего)',quizUi.customAnswer,256)
        imgui.InputTextWithHint('##quiz_custom_h',u8'Подсказка (необязательно)',quizUi.customHint,256)
        if styledButton('Выбрать свой вопрос',S(230),S(30),'primary') then
            quizGame.chooseCustom(readBuffer(quizUi.customQuestion),readBuffer(quizUi.customAnswer),readBuffer(quizUi.customHint))
        end
    end

    local half=splitW(2)
    if styledButton('Подготовить вопрос',half,S(34),'primary') then quizGame.prepareQuestion() end
    imgui.SameLine()
    if styledButton('Задать вопрос В ЭФИР',half,S(34),'primary') then
        if quizGame.prepareQuestion() then sendQuizDraft() end
    end
    if styledButton('Подсказка к текущему вопросу',S(280),S(30)) then quizGame.prepareHint() end
    if st.questionSent then
        imgui.TextColored(C.ok,u8'Вопрос этого раунда отправлен. Результат вводится ведущим.')
    end

    sectionLabel('Первый правильный ответ — вручную')
    muted('Посмотрите SMS в самой игре и сами впишите ник первого правильно ответившего. Ответ вводить необязательно.')
    imgui.SetNextItemWidth(S(195))
    imgui.InputTextWithHint('##quiz_nick',u8'Nick_Name',quizUi.nickname,64)
    imgui.SameLine()
    imgui.SetNextItemWidth(S(190))
    imgui.InputTextWithHint('##quiz_ans',u8'Что он ответил (по желанию)',quizUi.answer,160)
    imgui.SameLine()
    if styledButton('+1 балл##qaward',S(110),S(34),'primary') then
        if quizGame.award(readBuffer(quizUi.nickname),readBuffer(quizUi.answer)) then
            writeBuffer(quizUi.answer,160,'')
        end
    end
    if st.winner then
        imgui.TextColored(C.ok,u8(string.format('ПЕРВЫМ: %s  ·  СЧЁТ: %d',st.winner.name,st.winner.score)))
    end
    local third2=splitW(3)
    if styledButton('Объявить результат',third2,S(34),'primary') then quizGame.announceRound() end
    imgui.SameLine()
    if styledButton('Результат + эфир',third2,S(34)) then
        if quizGame.announceRound() then sendQuizDraft() end
    end
    imgui.SameLine()
    if styledButton('Следующий раунд',third2,S(34)) then quizGame.nextRound() end
    if styledButton('Отменить последний балл',S(230),S(29),'danger') then quizGame.undo() end

    sectionLabel('Таблица лидеров')
    local rows=quizGame.ranking()
    imgui.BeginChild('##quiz_ranking',V2(-1,S(140)),true)
    if #rows==0 then imgui.TextDisabled(u8'Никого пока нет. После проверки SMS начислите +1 балл вручную.') end
    for index,row in ipairs(rows) do
        imgui.TextColored(index==1 and C.accentHi or C.text,u8(string.format('%d. %s — %d балл.',index,row.name,row.score)))
        imgui.SameLine(S(390))
        if styledButton('+##qplus'..index,S(34),S(24)) then quizGame.adjust(row.name,1) end
        imgui.SameLine()
        if styledButton('-##qminus'..index,S(34),S(24)) then quizGame.adjust(row.name,-1) end
    end
    imgui.EndChild()
    if styledButton('Объявить лидеров',S(190),S(32)) then quizGame.leaderLine() end
    imgui.SameLine()
    if styledButton('ИТОГ КОНКУРСА',S(190),S(32),'primary') then quizGame.finish() end
    imgui.SameLine()
    if styledButton('Новый конкурс',S(170),S(32),'danger') then
        if quizGame.reset() then
            writeBuffer(quizUi.nickname,64,'');writeBuffer(quizUi.answer,160,'')
        end
    end
    sectionLabel('03 · Сценарий завершения — по порядку')
    muted('После последнего раунда пройдите шаги 1–6. Сначала проверьте таблицу и возможную ничью.')
    local nextEnd=nil
    for i=1,#quizGame.endSteps do
        if not st.endDone[tostring(i)] then nextEnd=i;break end
    end
    if nextEnd then
        imgui.TextColored(C.info,u8(string.format('Следующий шаг финала: %02d. %s',nextEnd,quizGame.endSteps[nextEnd].name)))
        if styledButton('В черновик##nextend',S(235),S(30),'primary') then
            quizGame.prepareStep('end',nextEnd)
        end
        imgui.SameLine()
        if styledButton('Отправить шаг финала##nextendsend',S(230),S(30)) then
            if quizGame.prepareStep('end',nextEnd) then sendQuizDraft() end
        end
    else
        imgui.TextColored(C.ok,u8'Все шаги завершения отправлены.')
    end
    if imgui.CollapsingHeader(u8'Полный пронумерованный список финала (6 шагов)##quizend') then
        for i,step in ipairs(quizGame.endSteps) do
            local completed=st.endDone[tostring(i)]==true
            imgui.TextColored(completed and C.ok or C.accentHi,u8(string.format('%02d. %s%s',i,step.name,completed and '  [OK]' or '')))
            muted('Когда: '..step.when)
            imgui.TextWrapped(u8(quizGame.phraseText(step.text)))
            if styledButton('В черновик##end'..i,S(155),S(29),'primary') then quizGame.prepareStep('end',i) end
            imgui.SameLine()
            if styledButton('Отправить шаг##endsend'..i,S(165),S(29)) then
                if quizGame.prepareStep('end',i) then sendQuizDraft() end
            end
            imgui.Separator()
        end
    end
    spacing(3)
    imgui.TextColored(C.info,u8(st.info))
    muted(st.championshipMode and
        'План чемпионата: 2 мин вступление, 25 вопросов по 25–35 секунд с короткими переходами, 1–2 мин финал. Возможен тай-брейк.'
        or 'Свободный эфир: выбирайте количество раундов и темп по ситуации. Таймер — подсказка ведущему.')
    spacing(8)
end

-- ── Раздел: Эфиры ────────────────────────────────────────────────
local function drawBroadcast()
    muted('Реплики собраны по «Правилам проведения эфиров» HOME News: заставка, знакомство, основной материал, вывод, прощание, заключительная музыка. Структура рекомендательная (п. 1.2).')

    if imgui.CollapsingHeader(u8'Правила проведения эфиров (кратко)') then
        bullet('Пиар в объявлениях должен чётко отражать тему эфира (п. 1.1).')
        bullet('Язык эфира — русский; исключения: названия транспорта, бизнесов, казино, классов и организаций (п. 1.3).')
        bullet('Запрещены мат, вульгарность и оскорбления — мут 30 минут (п. 1.4, 3.6). Ведущий отвечает за свои слова и за слова собеседников (п. 1.5).')
        bullet('Розыгрыши разрешены, если призы будут выданы. Призы — вирты, движимое и недвижимое имущество (п. 1.6, 1.7).')
        bullet('Розыгрыш без призов, с невыполнимыми условиями, обманом или в личных целях — ЧС фракции на 5 дней (п. 3.1).')
        bullet('Игровая статистика заменяется IC-определениями, реальные названия — IC-аналогами: Комптон = Гантон, Лос-Анджелес = Лос-Сантос, Калифорния = Сан-Андреас (п. 3.2).')
        bullet('Сбор средств для розыгрышей, аукционы и сбор денег на свой счёт или счёт редакции — default ban (п. 3.3, 3.4).')
        bullet('Антиреклама и антипиар — мут 15 минут (п. 3.5). Держите динамичный темп, избегайте длинных пауз (п. 3.7).')
        bullet('Добавлять участников в эфир, принимать SMS и звонки слушателей можно с 5-го ранга (п. 2.2).')
        spacing(4)
    end
    if imgui.CollapsingHeader(u8'Чек-лист перед эфиром') then
        for i, item in ipairs(airChecklistItems) do imgui.Checkbox(u8(item .. '##air' .. i), airChecklist[i]) end
        if styledButton('Сбросить отметки', S(180), S(28)) then
            for i = 1, #airChecklist do airChecklist[i][0] = false end
        end
        spacing(4)
    end

    sectionLabel('Формат')
    local perRow = 4
    local width = splitW(perRow)
    for i, mode in ipairs(mediaModes) do
        if (i - 1) % perRow ~= 0 then imgui.SameLine() end
        if styledButton(mode.name .. '##mode' .. i, width, S(34), i == selectedMediaMode and 'primary' or nil) then
            selectedMediaMode = i
            currentBroadcastStage = 1
        end
    end

    sectionLabel('Данные для подстановки')
    imgui.Columns(2, '##media_fields', false)
    imgui.TextColored(C.muted, u8'Тема эфира / лекции')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##media_topic', u8'Кратко укажите тему', mediaTopic, 256)
    imgui.NextColumn()
    imgui.TextColored(C.muted, u8'Ведущий (пусто = профиль)')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##media_host', u8'Из настроек, если оставить пустым', mediaHost, 128)
    imgui.NextColumn()
    imgui.TextColored(C.muted, u8'Гость / собеседник / победитель')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##media_guest', u8'Имя персонажа', mediaGuest, 128)
    imgui.NextColumn()
    imgui.TextColored(C.muted, u8'Источник информации')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##media_source', u8'Укажите источник и проверьте достоверность', mediaSource, 192)
    imgui.NextColumn()
    imgui.Columns(1)
    spacing(4)
    imgui.TextColored(C.muted, u8'Материал / приз / условия')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##media_material', u8'Вставьте проверенную информацию, приз или условия розыгрыша', mediaMaterial, 384)

    sectionLabel('Биндер этапов')
    if switchRow('binder', 'Отправлять реплики по Alt + Numpad+',
        'Каждое нажатие отправляет текущую реплику выбранного формата и переходит к следующей.', isBroadcastActive) then
        currentBroadcastStage = 1
    end
    local mode = mediaModes[selectedMediaMode]
    if isBroadcastActive[0] then
        local nextStage = mode.stages[currentBroadcastStage]
        if nextStage then
            dot(C.live)
            imgui.Text(u8(string.format('Следующая реплика (%d из %d): %s', currentBroadcastStage, #mode.stages, nextStage[1])))
        else
            imgui.TextColored(C.ok, u8'Все реплики набора отправлены. Нажмите «Сначала», чтобы пройти заново.')
        end
        if styledButton('Сначала', S(120), S(30)) then currentBroadcastStage = 1 end
    end

    sectionLabel('Текст для отправки')
    imgui.InputTextMultiline('##output', output, 4096, V2(-1, S(72)))
    local quarter = splitW(4)
    if styledButton('В строку чата', quarter, S(34), 'primary') then insertChatDraft() end
    imgui.SameLine()
    if styledButton('Отправить в чат', quarter, S(34), 'warn') then insertChatDraft(true) end
    tooltip('Отправит текст в игровой чат сразу, без подтверждения.')
    imgui.SameLine()
    if styledButton('Проверить по правилам', quarter, S(34)) then checkAir() end
    imgui.SameLine()
    if styledButton('В избранное', quarter, S(34)) then saveFavorite(mode.name .. ' · ' .. os.date('%H:%M')) end
    drawFindings()

    sectionLabel('Реплики')
    muted('Нажмите на название — текст загрузится в поле выше с подстановкой ваших данных.')
    spacing(4)
    for stageIndex, stage in ipairs(mode.stages) do
        local isNext = isBroadcastActive[0] and stageIndex == currentBroadcastStage
        if styledButton(stage[1] .. '##stage' .. stageIndex, S(200), S(32), isNext and 'primary' or nil) then
            selectMediaStage(stage)
        end
        imgui.SameLine(S(222))
        imgui.TextWrapped(u8(loadStageText(selectedMediaMode, stageIndex)))
        spacing(4)
    end
    spacing(8)
end

-- ── Раздел: Отыгровки ────────────────────────────────────────────
-- (внутри do-блока, чтобы не упереться в лимит 200 локальных переменных Lua)
local drawBinds
do
local bindUi = {
    group = 1, selected = 0, creating = false, armedDelete = false, armedGroup = false,
    name = buf(64), command = buf(32), lines = buf(2048), groupName = buf(48),
    delay = imgui.new.int(1200), original = imgui.new.bool(false), enabled = imgui.new.bool(true),
}

local function loadBindEditor(bind)
    writeBuffer(bindUi.name, 64, bind and bind.name or 'Новая отыгровка')
    writeBuffer(bindUi.command, 32, bind and bind.command or '/')
    writeBuffer(bindUi.lines, 2048, bind and bind.lines or '')
    bindUi.delay[0] = bind and bind.delay or 1200
    bindUi.original[0] = bind and bind.original or false
    bindUi.enabled[0] = bind == nil or bind.enabled ~= false
    bindUi.armedDelete = false
end

local function selectBind(index)
    local group = bindGroups[bindUi.group]
    bindUi.selected = index
    bindUi.creating = false
    loadBindEditor(group and group.binds[index])
end

local function newBind()
    bindUi.selected = 0
    bindUi.creating = true
    loadBindEditor(nil)
end

local function selectBindGroup(index)
    bindUi.group = index
    bindUi.armedGroup = false
    local group = bindGroups[index]
    if group and group.binds[1] then selectBind(1) else newBind() end
end

local function bindStatus(ok, message)
    if ok then setStatus(message, 0xFF79D8A2)
    else setStatus('Не удалось записать файл отыгровок. Проверьте доступ к папке MoonLoader.', 0xFF7777FF) end
end

local function saveBind()
    local group = bindGroups[bindUi.group]
    if not group then setStatus('Сначала создайте группу.', 0xFF60A8FF); return end
    local name = trimText(readBuffer(bindUi.name))
    local command = interviewApi.normalizeCommand(readBuffer(bindUi.command))
    local lines = trimText(readBuffer(bindUi.lines))
    local editingIndex = (not bindUi.creating and bindUi.selected > 0) and bindUi.selected or nil
    local existing = editingIndex and group.binds[editingIndex] or nil
    local stageId = existing and existing.flow_stage or nil
    if stageId then command = interviewApi.stages[stageId] end
    if name == '' then setStatus('Введите название отыгровки.', 0xFF7777FF); return end
    if not interviewApi.validBindCommand(command, stageId) then
        setStatus('Некорректная команда. /sv1 и /sv2 закреплены за этапами интервью.', 0xFF7777FF); return
    end
    if lines == '' then setStatus('Добавьте хотя бы одну строку отыгровки.', 0xFF7777FF); return end
    local owner = not stageId and bindCommandOwner(command, bindUi.group, editingIndex)
    if owner then setStatus('Команда ' .. command .. ' уже занята отыгровкой «' .. owner.name .. '».', 0xFF7777FF); return end
    local data = {
        name = name, command = command, lines = lines, delay = interviewApi.clampDelay(bindUi.delay[0]),
        original = stageId == nil and bindUi.original[0], enabled = bindUi.enabled[0], flow_stage = stageId,
    }
    if editingIndex then
        group.binds[editingIndex] = data
    else
        if #group.binds >= BIND_MAX_BINDS then setStatus('В группе уже максимум отыгровок.', 0xFF7777FF); return end
        group.binds[#group.binds + 1] = data
        bindUi.selected = #group.binds
        bindUi.creating = false
    end
    bindUi.delay[0] = data.delay
    writeBuffer(bindUi.command, 32, command)
    bindStatus(persistBinds(), 'Отыгровка сохранена. Команда ' .. command .. ' работает сразу.')
end

local function duplicateBind()
    local copy = {
        name = trimText(readBuffer(bindUi.name)) .. ' (копия)', command = '/', lines = readBuffer(bindUi.lines),
        delay = bindUi.delay[0], original = bindUi.original[0], enabled = true,
    }
    bindUi.selected = 0
    bindUi.creating = true
    loadBindEditor(copy)
    setStatus('Копия подготовлена — задайте новую команду и сохраните.', 0xFF60A8FF)
end

local function deleteBind()
    local group = bindGroups[bindUi.group]
    if not group or bindUi.creating or bindUi.selected < 1 or not group.binds[bindUi.selected] then return end
    if group.binds[bindUi.selected].flow_stage then
        setStatus('Этап интервью не удаляется. Измени его текст или выключи переключателем.', 0xFF60A8FF)
        return
    end
    if not bindUi.armedDelete then
        bindUi.armedDelete = true
        setStatus('Нажмите «Удалить» ещё раз, чтобы удалить отыгровку.', 0xFF60A8FF)
        return
    end
    table.remove(group.binds, bindUi.selected)
    bindStatus(persistBinds(), 'Отыгровка удалена.')
    if group.binds[1] then selectBind(math.min(bindUi.selected, #group.binds)) else newBind() end
end

local function playBindFromEditor()
    local lines = trimText(readBuffer(bindUi.lines))
    if lines == '' then setStatus('Нет строк для проигрывания.', 0xFF60A8FF); return end
    if not sampIsLocalPlayerSpawned or sampIsLocalPlayerSpawned() then
        if startBind({ delay = bindUi.delay[0], lines = lines, original = false }, '', nil) then
            setStatus('Проигрываю отыгровку (исходная команда в тесте не отправляется).', 0xFF79D8A2)
        end
    end
end

local function createBindGroup()
    local name = trimText(readBuffer(bindUi.groupName))
    if name == '' then setStatus('Введите название группы.', 0xFF7777FF); return end
    if #bindGroups >= BIND_MAX_GROUPS then setStatus('Достигнут максимум групп.', 0xFF7777FF); return end
    for _, group in ipairs(bindGroups) do
        if group.name:lower() == name:lower() then setStatus('Группа с таким названием уже есть.', 0xFF7777FF); return end
    end
    bindGroups[#bindGroups + 1] = { name = name:sub(1, 60), binds = {} }
    writeBuffer(bindUi.groupName, 48, '')
    selectBindGroup(#bindGroups)
    bindStatus(persistBinds(), 'Группа создана.')
end

local function renameBindGroup()
    local group = bindGroups[bindUi.group]
    local name = trimText(readBuffer(bindUi.groupName))
    if not group then return end
    if name == '' then setStatus('Введите новое название в поле группы.', 0xFF7777FF); return end
    group.name = name:sub(1, 60)
    writeBuffer(bindUi.groupName, 48, '')
    bindStatus(persistBinds(), 'Группа переименована.')
end

local function deleteBindGroup()
    local group = bindGroups[bindUi.group]
    if not group then return end
    for _, bind in ipairs(group.binds) do
        if bind.flow_stage then
            setStatus('Группа содержит этапы /sv1 и /sv2. Чтобы изменить их, редактируй отдельные строки.', 0xFF60A8FF)
            return
        end
    end
    if not bindUi.armedGroup then
        bindUi.armedGroup = true
        setStatus('Нажмите «Удалить группу» ещё раз: будут удалены все её отыгровки (' .. #group.binds .. ').', 0xFF60A8FF)
        return
    end
    table.remove(bindGroups, bindUi.group)
    bindUi.armedGroup = false
    bindStatus(persistBinds(), 'Группа удалена.')
    selectBindGroup(math.max(1, math.min(bindUi.group, #bindGroups)))
end

local function countLongLines(text)
    local count = 0
    for line in (text .. '\n'):gmatch('(.-)\r?\n') do
        if (utf8 and utf8.len and utf8.len(line) or #line) > 140 then count = count + 1 end
    end
    return count
end

drawBinds = function()
    if bindUi.group > #bindGroups then bindUi.group = math.max(1, #bindGroups) end
    muted('Спецпроект «Один вопрос — весь штат»: выбери группу «Интервью: Один вопрос» и правь этапы как обычные отыгровки. /sv1 — знакомство, затем вопрос; /sv2 — разрешение на фото, затем финал. /sv2 нет — без фото. /sv1 заново — новый участник.')
    spacing(5)
    muted('Изменения сохраняются в moonloader/config/LVNHelper/binds.json. Перейди в группу интервью, выбери этап, измени строки и нажми «Сохранить» — при следующем /sv1 или /sv2 применится новый текст.')
    muted('Обычные отыгровки работают по своим командам. Для /showpass и других серверных команд настройка исходной команды остаётся в редакторе.')
    if bindRunning then
        spacing(4)
        dot(C.live)
        imgui.Text(u8'Отыгровка выполняется…')
        imgui.SameLine()
        if styledButton('Остановить##bindstop', S(130), S(28), 'danger') then bindCancel = true end
    end

    sectionLabel('Группы')
    local group = bindGroups[bindUi.group]
    imgui.SetNextItemWidth(S(260))
    if imgui.BeginCombo('##bind_group', u8(group and group.name or 'Нет групп')) then
        for i, entry in ipairs(bindGroups) do
            if imgui.Selectable(u8(entry.name .. '##bg' .. i), bindUi.group == i) then selectBindGroup(i) end
        end
        imgui.EndCombo()
    end
    imgui.SameLine()
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##bind_group_name', u8'Название для новой группы или переименования', bindUi.groupName, 48)
    local third = splitW(3)
    if styledButton('Создать группу', third, S(30), 'primary') then createBindGroup() end
    imgui.SameLine()
    if styledButton('Переименовать', third, S(30)) then renameBindGroup() end
    imgui.SameLine()
    if styledButton('Удалить группу', third, S(30), 'danger') then deleteBindGroup() end

    sectionLabel('Отыгровки')
    local boxHeight = S(540)
    imgui.BeginChild('##bind_list', V2(S(250), boxHeight), true)
    if group then
        for i, bind in ipairs(group.binds) do
            if not bind.enabled then imgui.PushStyleColor(imgui.Col.Text, C.muted) end
            if imgui.Selectable(u8(bind.name .. '   ' .. bind.command .. '###bind' .. i), bindUi.selected == i and not bindUi.creating) then
                selectBind(i)
            end
            if not bind.enabled then imgui.PopStyleColor() end
        end
        if #group.binds == 0 then imgui.TextDisabled(u8'В группе пока нет отыгровок.') end
        spacing(4)
        if styledButton('+ Новая отыгровка', -1, S(34), 'primary') then newBind() end
    else
        imgui.TextDisabled(u8'Создайте группу выше.')
    end
    imgui.EndChild()
    imgui.SameLine()

    imgui.BeginChild('##bind_editor', V2(-1, boxHeight), true)
    if not group then
        imgui.TextDisabled(u8'Сначала создайте группу.')
    else
        imgui.TextColored(C.accentHi, u8(bindUi.creating and 'Новая отыгровка' or 'Редактирование'))
        spacing(2)
        imgui.Columns(2, '##bind_cols', false)
        imgui.TextColored(C.muted, u8'Название')
        imgui.SetNextItemWidth(-1)
        imgui.InputTextWithHint('##bind_name', u8'Например: Паспорт', bindUi.name, 64)
        imgui.NextColumn()
        imgui.TextColored(C.muted, u8'Команда в чате')
        imgui.SetNextItemWidth(-1)
        local selectedBind = not bindUi.creating and group.binds[bindUi.selected] or nil
        if selectedBind and selectedBind.flow_stage then
            imgui.TextColored(C.accentHi, u8(selectedBind.command .. '  (закреплена за этапом)'))
        else
            imgui.InputTextWithHint('##bind_command', u8'/showpass', bindUi.command, 32)
        end
        imgui.NextColumn()
        imgui.Columns(1)
        spacing(2)
        imgui.TextColored(C.muted, u8'Пауза между строками, мс')
        imgui.SetNextItemWidth(S(150))
        imgui.InputInt('##bind_delay', bindUi.delay, 100, 500)
        if bindUi.delay[0] < 200 then bindUi.delay[0] = 200 end
        if bindUi.delay[0] > 10000 then bindUi.delay[0] = 10000 end
        spacing(4)
        switchRow('bind_enabled', 'Отыгровка включена', nil, bindUi.enabled)
        if selectedBind and selectedBind.flow_stage then
            muted('Этот текст используется на соответствующем этапе /sv1 или /sv2. Каждый этап запускается отдельно, после ответа собеседника.')
        else
            switchRow('bind_original', 'Отправить исходную команду',
                'Нужно для серверных команд вроде /showpass: сначала RP-строки, затем команда уйдёт на сервер вместе с аргументами. Без этого переключателя команда только отыгрывается.', bindUi.original)
        end
        imgui.TextColored(C.muted, u8'Строки отыгровки (по одной в строке)')
        imgui.InputTextMultiline('##bind_lines', bindUi.lines, 2048, V2(-1, S(150)))
        local longLines = countLongLines(readBuffer(bindUi.lines))
        if longLines > 0 then
            imgui.PushStyleColor(imgui.Col.Text, C.warn)
            imgui.TextWrapped(u8('Строк длиннее 140 символов: ' .. longLines .. '. Чат сервера может их обрезать.'))
            imgui.PopStyleColor()
        end
        muted('Переменные: {host} — ведущий (имя из профиля), {name}, {rank}, {arg}, {id}. Служебные строки: {wait:2000} и {send} (для обычных отыгровок). Команды /me и /do берутся из настроек.')
        spacing(6)
        local quarter = splitW(4)
        if styledButton('Сохранить', quarter, S(34), 'primary') then saveBind() end
        imgui.SameLine()
        if styledButton('Проиграть', quarter, S(34)) then playBindFromEditor() end
        imgui.SameLine()
        if styledButton('Дублировать', quarter, S(34)) then duplicateBind() end
        imgui.SameLine()
        if styledButton(bindUi.armedDelete and 'Точно?' or 'Удалить', quarter, S(34), 'danger') then deleteBind() end
    end
    imgui.EndChild()

    spacing(6)
    if styledButton('Вернуть стандартные отыгровки', S(300), S(32)) then
        local added = restoreDefaultBinds()
        setStatus(added > 0 and ('Добавлено стандартных отыгровок: ' .. added .. '.') or 'Все стандартные отыгровки уже на месте.', 0xFF79D8A2)
        selectBindGroup(math.min(bindUi.group, math.max(1, #bindGroups)))
    end
    tooltip('Добавит удалённые стандартные отыгровки. Ваши изменения не затрагиваются.')
    imgui.TextDisabled(u8'Файл: moonloader/config/LVNHelper/binds.json')
    spacing(8)
end
end

