local function drawTools()
    sectionLabel('Таймер')
    imgui.Text(u8('Время на компьютере: ' .. os.date('%H:%M:%S')))
    muted('Таймер не получает данные сервера и не определяет PayDay. Введите известный вам интервал до нужного события.')
    spacing(4)
    imgui.TextColored(C.muted, u8'Интервал, минуты')
    imgui.SetNextItemWidth(S(120))
    imgui.InputTextWithHint('##payday_minutes', u8'60', paydayMinutes, 16)
    imgui.SameLine()
    for _, preset in ipairs({ 30, 60, 90 }) do
        if styledButton(preset .. ' мин##preset' .. preset, S(80), S(30)) then writeBuffer(paydayMinutes, 16, tostring(preset)) end
        imgui.SameLine()
    end
    if styledButton(paydayDeadline and 'Остановить##timer' or 'Запустить##timer', S(140), S(30), paydayDeadline and 'danger' or 'primary') then
        togglePaydayTimer()
    end
    spacing(4)
    local label = paydayText()
    local fraction = 0
    if paydayDeadline and paydayTotal > 0 then
        fraction = 1 - math.max(0, paydayDeadline - os.time()) / paydayTotal
    end
    imgui.ProgressBar(fraction, V2(-1, S(24)), u8(label))

    sectionLabel('Окна на экране')
    muted('Счёт конкурса ведётся вручную во вкладке «Битва умов».')
    if switchRow('chatdebug', 'Диагностика чата',
        'Показывает последние строки чата так, как их видит скрипт (без цветовых тегов).', chatDebug) then chatDebugLog = {} end
    if chatDebug[0] then
        imgui.BeginChild('##chat_debug', V2(-1, S(170)), true)
        if #chatDebugLog == 0 then imgui.TextDisabled(u8'Пока нет строк — дождитесь сообщений в чате.') end
        for _, entry in ipairs(chatDebugLog) do
            imgui.TextColored(C.muted, '[' .. entry.time .. ']')
            imgui.SameLine()
            imgui.TextWrapped(u8(entry.text))
        end
        if imgui.GetScrollY() >= imgui.GetScrollMaxY() - 5 then imgui.SetScrollHereY(1.0) end
        imgui.EndChild()
        if styledButton('Очистить##dbgclear', S(140), S(28)) then chatDebugLog = {} end
    end
    if switchRow('cheat', 'Шпаргалка по ПРО',
        'Короткая памятка по основным правилам прямо на экране.', showCheatSheet) then autoSave() end

    sectionLabel('Личные заметки о правилах организации')
    muted('Основа ПРО — текст, который вы передали как HOME. Сверяйте актуальную редакцию в закреплённых темах форума и с руководством. Здесь хранятся только ваши заметки.')
    spacing(4)
    imgui.InputTextMultiline('##organization_rules', orgRules, 4096, V2(-1, S(170)))
    if styledButton('Сохранить заметки', S(200), S(34), 'primary') then saveOrgRules() end
    spacing(8)
end

