-- ── Раздел: О скрипте ────────────────────────────────────────────
local function checkUpdates()
    updateCheckStatus = 'Проверяю версию…'
    local path = getWorkingDirectory() .. '\\version_server.ini'
    downloadUrlToFile(update_url, path, function(_, status)
        if status == 58 then
            local file = io.open(path, 'r')
            if file then
                local remoteVersion = file:read('*a'):gsub('%s+', '')
                file:close()
                os.remove(path)
                if remoteVersion ~= '' and remoteVersion ~= script_version then
                    updateCheckStatus = 'В репозитории указана версия ' .. remoteVersion .. '; локальная сборка ' .. script_version .. '. Установка обновлений только вручную.'
                elseif remoteVersion == script_version then
                    updateCheckStatus = 'Репозиторий и локальная сборка совпадают: ' .. script_version .. '. Установка обновлений только вручную.'
                else
                    updateCheckStatus = 'Сервер версий вернул пустой ответ.'
                end
            else updateCheckStatus = 'Не удалось прочитать ответ сервера версий.' end
        else
            updateCheckStatus = 'Проверка обновлений не удалась (код ' .. tostring(status) .. ').'
            os.remove(path)
        end
    end)
end

local dependencyRows
do
local function functionsPresent(names)
    local missing = {}
    for _, name in ipairs(names) do
        if type(_G[name]) ~= 'function' then missing[#missing + 1] = name end
    end
    return #missing == 0, table.concat(missing, ', ')
end

dependencyRows = function()
    local rows = {}
    local function add(name, ok, note) rows[#rows + 1] = { name = name, ok = ok, note = note } end
    add('mimgui, encoding, vkeys, lib.samp.events', true, 'загружены')
    local okSamp, missingSamp = functionsPresent({ 'sampRegisterChatCommand', 'sampSendChat', 'sampAddChatMessage',
        'sampIsDialogActive', 'sampSetCurrentDialogEditboxText', 'sampSetChatInputText', 'sampIsChatInputActive', 'isSampAvailable' })
    add('SAMPFUNCS', okSamp, okSamp and 'функции sampXXX доступны' or ('нет функций: ' .. missingSamp))
    local okMoon, missingMoon = functionsPresent({ 'encodeJson', 'decodeJson', 'downloadUrlToFile', 'setClipboardText',
        'getFolderPath', 'wasKeyPressed', 'isKeyDown', 'getScreenResolution', 'getCurrentCharWeapon' })
    add('MoonLoader API', okMoon, okMoon and 'все нужные функции есть' or ('нет функций: ' .. missingMoon))
    add('Шрифт с кириллицей', fontMain ~= nil, fontMain ~= nil and 'Segoe UI / Tahoma / Arial найден' or 'не найден в папке Fonts — текст может отображаться знаками «?»')
    add('Папка настроек', configWritable, configWritable and 'moonloader/config/LVNHelper доступна для записи' or 'нет доступа на запись — настройки и отыгровки не сохранятся')
    add('Отыгровки', #bindGroups > 0, #bindGroups > 0 and (#bindGroups .. ' групп загружено') or 'список пуст — нажмите «Вернуть стандартные» в разделе «Отыгровки»')
    return rows
end
end

local function drawAbout()
    sectionLabel('Как пользоваться')
    bullet('/lvn — открыть или закрыть окно LV News Helper.')
    bullet('Объявления: выберите шаблон, заполните поля, соберите черновик и проверьте его по ПРО.')
    bullet('Для объявлений откройте игровой диалог, для /me и /do — строку чата, затем нажмите кнопку вставки или сочетание клавиш.')
    bullet('Проверьте текст и отправьте его сами штатным способом.')

    sectionLabel('Команды из заготовок и правил')
    bullet('/me — RP-действие персонажа от первого лица; примеры есть в разделе «Эфиры».')
    bullet('/do — RP-описание обстановки или видимого результата.')
    bullet('/carpass — команда сервера для проверки параметров транспорта; хелпер её не запускает.')
    bullet('/radio 1 — пример OOC-канала из правил; это не рекламная частота и не команда хелпера.')
    bullet('/ad — игровая команда подачи объявления; хелпер её не запускает.')
    bullet('[B] и [I] — теги форматирования из примера ChatBox, а не команды.')
    spacing(4)
    muted('Хелпер регистрирует только команду /lvn. Тег в /r и /f меняется только при включённой настройке. Для работы нужны MoonLoader, mimgui, encoding и vkeys.')

    sectionLabel('Проверка зависимостей')
    for _, row in ipairs(dependencyRows()) do
        dot(row.ok and C.ok or C.bad)
        imgui.Text(u8(row.name))
        imgui.SameLine(S(300))
        imgui.TextColored(row.ok and C.muted or C.bad, u8(row.note))
    end

    sectionLabel('Обновления')
    if profile.support.updates_ready then
        if styledButton('Проверить обновления', S(220), S(34), 'primary') then checkUpdates() end
        spacing(2)
        muted(updateCheckStatus)
    else
        muted('Проверка обновлений будет доступна после публикации репозитория и version.ini.')
    end

    sectionLabel('Разработка и поддержка (Vampir2615)')
    muted('LVN Helper бесплатный. Поддержать автора можно добровольно.')
    spacing(4)
    if styledButton('Скопировать Telegram: ' .. profile.support.telegram, -1, S(34)) then
        setClipboardText(toCp(profile.support.telegram))
        setStatus('Контакт Telegram скопирован.', 0xFF79D8A2)
    end
    if styledButton('Скопировать адрес USDT (TRC20)', -1, S(34)) then
        setClipboardText(profile.support.usdt_trc20)
        setStatus('Адрес USDT TRC20 скопирован.', 0xFF79D8A2)
    end
    muted('USDT: используйте только сеть TRON (TRC20). Перевод в другой сети может привести к потере средств.')
    if profile.support.github_issues_url ~= '' then
        if styledButton('Скопировать ссылку GitHub Issues', -1, S(34)) then
            setClipboardText(profile.support.github_issues_url)
            setStatus('Ссылка на сообщения об ошибках скопирована.', 0xFF79D8A2)
        end
    else
        muted('GitHub Issues появится после создания репозитория.')
    end
    if profile.support.blasthack_thread_url ~= '' then
        if styledButton('Скопировать ссылку на тему BlastHack', -1, S(34)) then
            setClipboardText(profile.support.blasthack_thread_url)
            setStatus('Ссылка BlastHack скопирована.', 0xFF79D8A2)
        end
    else
        muted('Ссылка на BlastHack появится после публикации темы.')
    end
    spacing(8)
end

-- ── Раздел: готовый эфир «Сан-Андреас за кадром» ────────────────
local function drawAirProgram()
    local a=airProgram
    sectionLabel('Выбрать выпуск · 103.3 FM')
    local episode=a.episodes[a.episodeIndex]
    imgui.SetNextItemWidth(-1)
    if imgui.BeginCombo('##air_episode_selector',u8(string.format('Выпуск №%d — %s',a.episodeIndex,a.title))) then
        for i,item in ipairs(a.episodes) do
            local option=string.format('№%d — %s (%d реплик)',i,item.title,#item.lines)
            if imgui.Selectable(u8(option..'##aired'..i),a.episodeIndex==i) then a.selectEpisode(i) end
        end
        imgui.EndCombo()
    end
    episode=a.episodes[a.episodeIndex]
    muted(string.format('Выпуск №%d: %s. %d пронумерованных реплик, около %s минут. Без гостей и SMS.',
        a.episodeIndex,a.title,#a.lines,episode.minutes or '18'))
    local sent=a.countSent()
    imgui.ProgressBar(sent/#a.lines,V2(-1,S(24)),u8(string.format('Выполнено: %d / %d',sent,#a.lines)))
    local elapsed='не начат'
    if a.startedAt>0 then
        local seconds=math.max(0,os.time()-a.startedAt)
        elapsed=string.format('%02d:%02d',math.floor(seconds/60),seconds%60)
    end
    imgui.TextColored(C.info,u8(string.format('Реплика: %03d/%03d   |   Эфир: %s',a.current,#a.lines,elapsed)))
    muted('Перед началом включите эфир через игровое /n. Заставки являются текстовыми, не звуковыми файлами.')

    sectionLabel('Быстрый переход по частям эфира')
    local chapterIndex=1
    for i,ch in ipairs(a.chapters) do
        if a.current>=ch.first and a.current<=ch.last then chapterIndex=i;break end
    end
    imgui.SetNextItemWidth(-1)
    if imgui.BeginCombo('##air_chapter',u8(a.chapters[chapterIndex].name)) then
        for i,ch in ipairs(a.chapters) do
            local text=string.format('%d. %s  (%03d–%03d)',i,ch.name,ch.first,ch.last)
            if imgui.Selectable(u8(text..'##chapter'..i),i==chapterIndex) then
                a.prepare(ch.first,true)
            end
        end
        imgui.EndCombo()
    end
    local third=splitW(3)
    if styledButton('К началу##air_start',third,S(31)) then a.prepare(1,true) end
    imgui.SameLine()
    if styledButton('К финалу##air_final',third,S(31)) then a.prepare(a.chapters[#a.chapters].first,true) end
    imgui.SameLine()
    if styledButton('Анонс эфира##air_ad',third,S(31)) then
        a.setSpecial(a.episodes[a.episodeIndex].promo)
    end
    sectionLabel('Сценарий по порядку')
    local half=splitW(2)
    if styledButton('← Предыдущая##air_prev',half,S(32)) then a.prepare(a.current-1,true) end
    imgui.SameLine()
    if styledButton('Следующая →##air_next',half,S(32),'primary') then a.prepare(a.current+1,true) end
    imgui.TextColored(C.accentHi,u8(('РЕПЛИКА %03d'):format(a.current)))
    imgui.TextWrapped(u8(profile.apply(a.lines[a.current] or '')))
    spacing(5)
    imgui.BeginChild('##air_script_list',V2(-1,S(245)),true)
    for i,line in ipairs(a.lines) do
        local done=a.sent[tostring(i)] and '✓ ' or ''
        local title=string.format('%s%03d · %s###airline%d',done,i,profile.apply(line),i)
        if imgui.Selectable(u8(title),a.current==i) then a.prepare(i,true) end
        if a.needsScroll and a.current==i then
            imgui.SetScrollHereY(0.40)
            a.needsScroll=false
        end
    end
    imgui.EndChild()
    sectionLabel('Управление сценарием')
    local left=splitW(2)
    if styledButton('Отметить шаг выполненным##air_mark',left,S(32)) then a.markDone() end
    imgui.SameLine()
    if styledButton(a.resetArmed and 'Подтвердить сброс##air_reset' or 'Сбросить прогресс##air_reset',left,S(32),'danger') then a.reset() end
    imgui.TextColored(C.info,u8(a.info))
    spacing(6)
end

