    { name = 'Эфиры',       hint = 'Реплики для собеседований, эфиров и интервью',      draw = drawBroadcast },
    { name = 'Отыгровки',   hint = 'Свои отыгровки по командам: /showpass и любые другие', draw = drawBinds },
    { name = 'Битва умов',   hint = 'Чемпионат 10/7/8, сценарий, вопросы, реплики и очки', draw = drawQuiz },
    { name = 'За кадром',     hint = 'Два полных выпуска, выбор сценария и пульт ведущего', draw = drawAirProgram },
    { name = 'Инструменты', hint = 'Таймер, окна на экране и личные заметки',           draw = drawTools },
