local function drawSidebar(height)
    imgui.PushStyleColor(imgui.Col.ChildBg, C.side)
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, V2(S(12), S(16)))
    imgui.BeginChild('##sidebar', V2(S(210), height), true)
    imgui.PopStyleVar()

    if fontTitle then imgui.PushFont(fontTitle) end
    imgui.TextColored(C.text, u8'LV News')
    if fontTitle then imgui.PopFont() end
    imgui.TextColored(C.accentHi, u8'Помощник редактора')
    spacing(12)

    local style = imgui.GetStyle()
    style.ButtonTextAlign = V2(0, 0.5)
    for i, section in ipairs(sections) do
        local active = i == currentSection
        imgui.PushStyleColor(imgui.Col.Button, active and V4(0.58, 0.42, 0.98, 0.20) or C.clear)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, active and V4(0.58, 0.42, 0.98, 0.30) or C.neutral)
        imgui.PushStyleColor(imgui.Col.ButtonActive, C.accentLo)
        imgui.PushStyleColor(imgui.Col.Text, active and C.accentHi or C.text)
        local suffix = ''
        if i == 2 and #favorites > 0 then suffix = '  (' .. #favorites .. ')' end
        if imgui.Button(u8('   ' .. section.name .. suffix .. '###nav' .. i), V2(-1, S(38))) then currentSection = i end
        imgui.PopStyleColor(4)
        if active then
            local a, b = imgui.GetItemRectMin(), imgui.GetItemRectMax()
            imgui.GetWindowDrawList():AddRectFilled(
                V2(a.x, a.y + S(8)), V2(a.x + S(3), b.y - S(8)), imgui.GetColorU32Vec4(C.accent), S(2))
        end
    end
    style.ButtonTextAlign = V2(0.5, 0.5)

    -- Нижний блок: активные режимы и версия
    local footerHeight = S(100)
    local free = imgui.GetContentRegionAvail().y
    if free > footerHeight then imgui.SetCursorPosY(imgui.GetCursorPosY() + free - footerHeight) end
    if isBroadcastActive[0] then dot(C.live); imgui.TextColored(C.text, u8'Биндер эфира включён') end
    if bindRunning then dot(C.live); imgui.TextColored(C.text, u8'Идёт отыгровка') end
    if dndMode[0] then dot(C.warn); imgui.TextColored(C.text, u8'Не беспокоить') end
    imgui.TextDisabled(u8('Версия ' .. script_version))

    imgui.EndChild()
    imgui.PopStyleColor()
end

-- Закреплённый пульт: виден независимо от прокрутки вопросов и таблицы.
local function drawQuizFooter()
    imgui.TextColored(C.accentHi,u8'ПУЛЬТ ЭФИРА · текст можно исправить перед отправкой')
    imgui.InputTextMultiline('##quiz_sticky_draft',output,4096,V2(-1,S(54)))
    local third=splitW(3)
    if styledButton('ОТПРАВИТЬ В ЭФИР',third,S(36),'primary') then sendQuizDraft() end
    imgui.SameLine()
    if styledButton('В строку чата',third,S(36)) then insertChatDraft(false) end
    imgui.SameLine()
    if styledButton('Открыть /n',third,S(36)) then
        local ok,err=pcall(sampSendChat,'/n')
        if not ok then setStatus('Ошибка меню /n: '..tostring(err),0xFF7777FF) end
    end
end

-- Закреплённый пульт радиопутешествия: не пропадает при прокрутке списка.
local function drawAirProgramFooter()
    imgui.TextColored(C.accentHi,u8'ПУЛЬТ ЭФИРА · текст выбранной реплики можно исправить')
    imgui.InputTextMultiline('##air_sticky_draft',airProgram.draft,1024,V2(-1,S(54)))
    local third=splitW(3)
    if styledButton('ОТПРАВИТЬ В ЭФИР',third,S(36),'primary') then airProgram.send() end
    imgui.SameLine()
    if styledButton('В строку чата',third,S(36)) then airProgram.putInChat() end
    imgui.SameLine()
    if styledButton('Открыть /n',third,S(36)) then
        local ok,err=pcall(sampSendChat,'/n')
        if not ok then setStatus('Ошибка открытия /n: '..tostring(err),0xFF7777FF) end
    end
end

local function drawContent(height)
    local width = imgui.GetContentRegionAvail().x
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, V2(S(20), S(14)))
    imgui.BeginChild('##content_pane', V2(width, height), true)
    imgui.PopStyleVar()

    local section = sections[currentSection]
    if fontTitle then imgui.PushFont(fontTitle) end
    imgui.Text(u8(section.name))
    if fontTitle then imgui.PopFont() end
    imgui.TextColored(C.muted, u8(section.hint))
    spacing(4)

    local isQuiz = section.name == 'Битва умов'
    local isAir = section.name == 'За кадром'
    local body = imgui.GetContentRegionAvail().y - ((isQuiz or isAir) and S(181) or S(34))
    imgui.BeginChild('##section_body', V2(-1, math.max(S(100), body)), false)
    section.draw()
    imgui.EndChild()

    if isQuiz then drawQuizFooter()
    elseif isAir then drawAirProgramFooter() end
    imgui.Separator()
    spacing(2)
    dot(statusColor)
    imgui.Text(u8(statusText ~= '' and statusText or 'Готов к работе.'))

    imgui.EndChild()
end

local mainFrame = imgui.OnFrame(function() return opened[0] end, function(self)
    local screenW, screenH = getScreenResolution()
    imgui.SetNextWindowPos(V2(screenW / 2, screenH / 2), imgui.Cond.FirstUseEver, V2(0.5, 0.5))
    imgui.SetNextWindowSize(V2(S(980), S(660)), imgui.Cond.FirstUseEver)
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, V2(0, 0))
    local visible = imgui.Begin(u8'LV News Helper##main', opened,
        imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
    imgui.PopStyleVar()
    if visible then
        local height = imgui.GetContentRegionAvail().y
        drawSidebar(height)
        imgui.SameLine(0, 0)
        drawContent(height)
    end
    imgui.End()
end)

-- Окна-подсказки живут в отдельном кадре с HideCursor: иначе пока включены
-- Шпаргалка выводится отдельно, без захвата курсора во время игры.
local overlayFrame = imgui.OnFrame(function() return showCheatSheet[0] end, function(self)
    self.HideCursor = true
    if showCheatSheet[0] then
        imgui.SetNextWindowSize(V2(S(440), S(260)), imgui.Cond.FirstUseEver)
        imgui.SetNextWindowPos(V2(S(20), S(60)), imgui.Cond.FirstUseEver)
        imgui.SetNextWindowBgAlpha(0.88)
        if imgui.Begin(u8'Шпаргалка ПРО##cheat', showCheatSheet, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoFocusOnAppearing) then
            bullet('Транспорт: сверяйте название и класс с данными сервера.')
            bullet('Недвижимость: квартиры запрещены для покупки и продажи по переданному ПРО HOME.')
            bullet('ChatBox: проверьте обязательный префикс [ChatBox].')
            bullet('Эфир: пиар по теме, без мата, сбора средств и аукционов; реальные города и статистику заменяйте на IC.')
            bullet('SMS и звонки слушателей — с 5-го ранга.')
            spacing(4)
            imgui.TextDisabled(u8'Проверка в хелпере — только подсказка. Финально сверяйтесь с актуальным ПРО.')
        end
        imgui.End()
    end
end)

-- ── Шрифты и тема ────────────────────────────────────────────────
local function loadFont(files, size)
    local folder = getFolderPath(0x14) .. '\\'
    for _, file in ipairs(files) do
        if doesFileExist(folder .. file) then
            return imgui.GetIO().Fonts:AddFontFromFileTTF(folder .. file, size, nil, fontRanges)
        end
    end
    return nil
end

local function applyTheme()
    local style = imgui.GetStyle()
    style.WindowRounding = S(10)
    style.ChildRounding = S(8)
    style.FrameRounding = S(6)
    style.PopupRounding = S(6)
    style.ScrollbarRounding = S(8)
    style.GrabRounding = S(6)
    style.WindowBorderSize = 1
    style.ChildBorderSize = 1
    style.FrameBorderSize = 0
    style.ScrollbarSize = S(12)
    style.FramePadding = V2(S(10), S(6))
    style.ItemSpacing = V2(S(10), S(8))
    style.ItemInnerSpacing = V2(S(8), S(6))
    style.WindowTitleAlign = V2(0.5, 0.5)
    style.ButtonTextAlign = V2(0.5, 0.5)

    local c, col = imgui.Col, style.Colors
    col[c.Text] = C.text
    col[c.TextDisabled] = C.muted
    col[c.WindowBg] = C.bg
    col[c.ChildBg] = C.clear
    col[c.PopupBg] = V4(0.075, 0.085, 0.120, 0.99)
    col[c.Border] = C.line
    col[c.FrameBg] = C.frame
    col[c.FrameBgHovered] = V4(0.160, 0.175, 0.245, 1)
    col[c.FrameBgActive] = V4(0.205, 0.205, 0.320, 1)
    col[c.TitleBg] = V4(0.030, 0.036, 0.056, 1)
    col[c.TitleBgActive] = V4(0.075, 0.062, 0.140, 1)
    col[c.TitleBgCollapsed] = V4(0.030, 0.036, 0.056, 1)
    col[c.ScrollbarBg] = C.clear
    col[c.ScrollbarGrab] = V4(0.22, 0.24, 0.34, 1)
    col[c.ScrollbarGrabHovered] = V4(0.32, 0.34, 0.48, 1)
    col[c.ScrollbarGrabActive] = C.accentLo
    col[c.CheckMark] = C.accentHi
    col[c.SliderGrab] = C.accent
    col[c.SliderGrabActive] = C.accentHi
    col[c.Button] = C.neutral
    col[c.ButtonHovered] = C.neutralHi
    col[c.ButtonActive] = C.neutralLo
    col[c.Header] = V4(0.58, 0.42, 0.98, 0.22)
    col[c.HeaderHovered] = V4(0.58, 0.42, 0.98, 0.34)
    col[c.HeaderActive] = V4(0.58, 0.42, 0.98, 0.48)
    col[c.Separator] = C.line
    col[c.SeparatorHovered] = C.accent
    col[c.SeparatorActive] = C.accentHi
    col[c.ResizeGrip] = V4(0.58, 0.42, 0.98, 0.25)
    col[c.ResizeGripHovered] = V4(0.58, 0.42, 0.98, 0.60)
    col[c.ResizeGripActive] = C.accent
    col[c.TextSelectedBg] = V4(0.58, 0.42, 0.98, 0.40)
    col[c.PlotHistogram] = C.accent
    col[c.PlotHistogramHovered] = C.accentHi
end

imgui.OnInitialize(function()
    imgui.GetIO().IniFilename = nil
    local _, screenH = getScreenResolution()
    uiScale = math.max(0.85, math.min(1.6, screenH / 1080))

    -- Кириллица, латиница и общая пунктуация (тире, многоточие, кавычки).
    fontRanges = imgui.new.ImWchar[7](0x0020, 0x00FF, 0x0400, 0x052F, 0x2010, 0x205E, 0)
    fontMain = loadFont({ 'segoeui.ttf', 'tahoma.ttf', 'arial.ttf' }, S(16))
    fontTitle = loadFont({ 'segoeuib.ttf', 'tahomabd.ttf', 'arialbd.ttf' }, S(23))
    applyTheme()
end)
